(function initWageEngine(root) {
  "use strict";
  const app = (root.MWILayuEnhancement = root.MWILayuEnhancement || {});
  function create({ config, rules = {}, character = {}, market = { marketData: {} }, math = app.wageMath, acquisitionSource = null }) {
    const itemDetailMap = rules.itemDetailMap || {};
    const characterSkills = character.characterSkills || [];
    const characterItems = character.characterItems || [];
    const characterHouseRoomMap = character.characterHouseRoomMap || {};
    const characterActionTypeDrinkSlotsMap = character.actionTypeDrinkSlotsMap || {};
    const characterAchievementActionTypeBuffsMap = character.achievementActionTypeBuffsMap || {};
    const characterCommunityActionTypeBuffsMap = character.communityActionTypeBuffsMap || {};
    const mooncakeCharacterCalcSignature = "explicit-input";
    const mooncakeMarketPricingRevision = 0;
    const getInitClientData = () => rules;
    const getMarketData = () => market;
    // Host adapter: a calculator owns one rules snapshot. Re-enumerating the
    // entire dictionary inside every price/protection/route lookup is quadratic
    // in a large collection. A rules update creates a new calculator.
    const hasItemDetails = Object.keys(itemDetailMap).length > 0;
    const mooncakeEnsureItemDetailMap = () => hasItemDetails;
    const mooncakeEnsureCharacterData = () => {};
    const mooncakeBuildCharacterCalcSignature = () => mooncakeCharacterCalcSignature;
    const getEnhancelateTotalSkillLevel = () => Object.values(characterSkills).reduce((sum, skill) => sum + (Number(skill.level) || 0), 0);
// Host override authorized 2026-10-15: sale tax is 4%; pinned upstream used 5%.
const MOONCAKE_MARKET_SELL_TAX_RATE = 0.04;

const MOONCAKE_MARKET_SELL_NET_FACTOR = 1 - MOONCAKE_MARKET_SELL_TAX_RATE;

const DEFAULT_VIRTUAL_CONFIG = {
        enabled: false,
        enhancing_level: 150,
        laboratory_level: 8,
        enhancer_type: 'starry',
        enhancer_level: 20,
        enhancers_top_level: 12,
        enhancers_bottom_level: 12,
        necklace_level: 7,
        glove_level: 15,
        chance_cape_type: 'refined',
        chance_cape_level: 8,
        drink_pouch_level: 12,
        tea_type: 'ultra',
        champion_achievement: true,
        // `system` follows the live community buff. A numeric level is a
        // virtual override, including 0 for no community enhancing buff.
        community_enhancing_speed_level: 'system'
    };

const MOONCAKE_HOURLY_WAGE_TIER_KEYS = Object.freeze([
        'loss', 'red', 'orange', 'gold', 'lightGreen', 'brightGreen'
    ]);

const MOONCAKE_DEFAULT_HOURLY_WAGE_COLOR_PROFILE = Object.freeze({
        thresholdsM: Object.freeze([3, 8, 15, 30]),
        colors: Object.freeze({
            loss: '#888888',
            red: '#F87171',
            orange: '#FF9F45',
            gold: '#FFD166',
            lightGreen: '#A8E6CF',
            brightGreen: '#7DFFB3'
        })
    });

const MOONCAKE_HOURLY_WAGE_COLOR_PROFILE_MAX_M = 1000000;

const MOONCAKE_BASE_ITEM_COST_PRICE_SOURCE_KEYS = Object.freeze([
        'ask', 'askMinusOne', 'bidPlusOne', 'bid'
    ]);

const MOONCAKE_DEFAULT_BASE_ITEM_COST_PRICE_POLICY = Object.freeze({
        material: Object.freeze(['ask', 'bid']),
        product: 'ask'
    });

const MOONCAKE_BASE_ITEM_COST_RESOLUTION_CACHE_LIMIT = 128;

const mooncakeBaseItemCostResolutionCaches = new WeakMap();

const MOONCAKE_COMMUNITY_ENHANCING_SPEED_TYPE_HRID = '/community_buff_types/enhancing_speed';

const MOONCAKE_COMMUNITY_ENHANCING_SPEED_SOURCE_HRID = '/buff_uniques/enhancing_community_buff';

const MOONCAKE_ENHANCING_ACTION_TYPE_HRID = '/action_types/enhancing';

function mooncakeNormalizeVirtualEnhancingCommunityBuffLevel(value) {
        if (value === 'system' || value === 'follow-system' || value === 'follow_system' || value == null || value === '') {
            return 'system';
        }
        const numeric = Number(value);
        if (!Number.isFinite(numeric)) return 'system';
        return Math.max(0, Math.min(20, Math.round(numeric)));
    }

function mooncakeIsEnhancingCommunityBuffEnabled() {
        return config.features?.enhancingCommunityBuff !== false;
    }

function mooncakeGetVirtualEnhancingCommunityBuffLevel() {
        return mooncakeNormalizeVirtualEnhancingCommunityBuffLevel(
            config.virtual?.community_enhancing_speed_level
        );
    }

function mooncakeGetCommunityEnhancingSpeedDefinition() {
        const initData = getInitClientData?.();
        const buff = initData?.communityBuffTypeDetailMap?.[MOONCAKE_COMMUNITY_ENHANCING_SPEED_TYPE_HRID]?.buff;
        const base = Number(buff?.flatBoost);
        const perLevel = Number(buff?.flatBoostLevelBonus);
        return {
            // The live init data currently defines level 1 as 20% and each
            // following level as +0.5%. Keep the data values authoritative.
            base: Number.isFinite(base) ? base : 0.20,
            perLevel: Number.isFinite(perLevel) ? perLevel : 0.005
        };
    }

function mooncakeGetCommunityEnhancingSpeedBonusForLevel(level) {
        const normalizedLevel = Math.max(0, Math.min(20, Math.round(Number(level) || 0)));
        if (!normalizedLevel) return 0;
        const definition = mooncakeGetCommunityEnhancingSpeedDefinition();
        // Keep the data-defined percentage stable (for example level 20 is
        // exactly 29.5%, not a binary floating-point tail in cache keys/UI).
        return Math.round((definition.base + definition.perLevel * (normalizedLevel - 1)) * 100000) / 1000;
    }

function mooncakeGetLiveEnhancingCommunityBuffLevel() {
        const buffs = mooncakeCollectionValues(
            mooncakeGetMapEntry(characterCommunityActionTypeBuffsMap, MOONCAKE_ENHANCING_ACTION_TYPE_HRID)
        );
        if (!buffs.length) return 0;
        const definition = mooncakeGetCommunityEnhancingSpeedDefinition();
        for (const buff of buffs) {
            const uniqueHrid = String(buff?.uniqueHrid || '');
            const typeHrid = String(buff?.typeHrid || '');
            if (uniqueHrid !== MOONCAKE_COMMUNITY_ENHANCING_SPEED_SOURCE_HRID && typeHrid !== '/buff_types/action_speed') continue;
            const directLevel = Number(buff?.communityBuffLevel ?? buff?.communityLevel ?? buff?.level);
            if (Number.isFinite(directLevel)) return Math.max(0, Math.min(20, Math.round(directLevel)));
            const flatBoost = Number(buff?.flatBoost);
            if (!Number.isFinite(flatBoost) || !(definition.perLevel > 0)) continue;
            const inferred = Math.round((flatBoost - definition.base) / definition.perLevel) + 1;
            const expectedFlatBoost = definition.base + definition.perLevel * (inferred - 1);
            if (inferred >= 1 && inferred <= 20 && Math.abs(flatBoost - expectedFlatBoost) < 1e-6) return inferred;
        }
        return 0;
    }

function mooncakeGetEffectiveEnhancingCommunityBuffLevel() {
        const virtualLevel = config.virtual?.enabled ? mooncakeGetVirtualEnhancingCommunityBuffLevel() : 'system';
        if (virtualLevel !== 'system') return virtualLevel;
        return mooncakeIsEnhancingCommunityBuffEnabled() ? mooncakeGetLiveEnhancingCommunityBuffLevel() : 0;
    }

const MOONCAKE_ENHANCEMENT_STANDARD_HOURLY_DEFAULT_M = 15;

const MOONCAKE_ENHANCEMENT_STANDARD_HOURLY_MAX_M = 1000000;

function mooncakeNormalizeEnhancementRouteObjective(value) {
        if (value === 'hourly' || value === 'maxHourly') return 'hourly';
        if (value === 'profit' || value === 'minCost') return 'profit';
        // Keep saved selections from the former "综合策略" working, but give
        // them the new price-independent standard-hourly behavior.
        if (value === 'standard' || value === 'standardHourly' ||
            value === 'balanced' || value === 'combined' || value === 'comprehensive') return 'standard';
        return null;
    }

function getEnhancementRouteObjective() {
        return mooncakeNormalizeEnhancementRouteObjective(config.preferences?.enhancementRouteObjective) || 'hourly';
    }

function mooncakeGetEnhancementStandardHourlyM() {
        const value = Number(config.preferences?.enhancementStandardHourlyM);
        if (!Number.isFinite(value)) return MOONCAKE_ENHANCEMENT_STANDARD_HOURLY_DEFAULT_M;
        return Math.min(
            MOONCAKE_ENHANCEMENT_STANDARD_HOURLY_MAX_M,
            Math.max(0, value)
        );
    }

function mooncakeGetEnhancementStandardHourlyWage() {
        return mooncakeGetEnhancementStandardHourlyM() * 1e6;
    }

function mooncakeGetEnhancementRouteSelectionMode(value = null) {
        const objective = mooncakeNormalizeEnhancementRouteObjective(value) || getEnhancementRouteObjective();
        if (objective === 'standard') return 'standard';
        return objective === 'profit' ? 'minCost' : 'maxHourly';
    }

function mooncakeNormalizeBaseItemCostPriceSourceList(value, fallback = []) {
        if (!Array.isArray(value)) return [...fallback];
        const seen = new Set();
        const normalized = [];
        for (const source of value) {
            if (!MOONCAKE_BASE_ITEM_COST_PRICE_SOURCE_KEYS.includes(source) || seen.has(source)) continue;
            seen.add(source);
            normalized.push(source);
        }
        // An empty list is an intentional user choice that disables a route.
        // A non-empty list with no recognized source is corrupted old data,
        // so restore the supplied safe default instead of disabling it.
        if (value.length && !normalized.length) return [...fallback];
        return normalized;
    }

function mooncakeNormalizeBaseItemCostPriceSource(value, fallback = 'ask') {
        if (MOONCAKE_BASE_ITEM_COST_PRICE_SOURCE_KEYS.includes(value)) return value;
        // v1.6.108 and earlier stored ready-made quotes as an ordered array.
        // Keep its first valid choice when migrating to the explicit single
        // quote model, so existing users retain their previous priority.
        if (Array.isArray(value)) {
            const firstValid = value.find(source => MOONCAKE_BASE_ITEM_COST_PRICE_SOURCE_KEYS.includes(source));
            if (firstValid) return firstValid;
        }
        return MOONCAKE_BASE_ITEM_COST_PRICE_SOURCE_KEYS.includes(fallback) ? fallback : 'ask';
    }

function mooncakeNormalizeBaseItemCostPricePolicy(value) {
        const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
        return {
            material: mooncakeNormalizeBaseItemCostPriceSourceList(
                source.material,
                MOONCAKE_DEFAULT_BASE_ITEM_COST_PRICE_POLICY.material
            ),
            product: mooncakeNormalizeBaseItemCostPriceSource(
                source.product,
                MOONCAKE_DEFAULT_BASE_ITEM_COST_PRICE_POLICY.product
            )
        };
    }

function mooncakeGetBaseItemCostPricePolicy() {
        return mooncakeNormalizeBaseItemCostPricePolicy(config.preferences?.baseItemCostPricePolicy);
    }

function mooncakeGetBaseItemCostProductPriceSource() {
        return mooncakeGetBaseItemCostPricePolicy().product;
    }

let marketDataCache = null;

function calcEnhancingSecondsPerAction(itemHrid) {
        const BASE_SPEED = 12;
        const playerParams = getPlayerEnhanceParams();
        const itemLevel = getBaseItemLevel(itemHrid);
        const drinkConcentrationBonus = playerParams.drink_concentration_bonus || 0;
        const dcm = 1 + drinkConcentrationBonus / 100;
        const tea = playerParams;
        const effectiveLevel = playerParams.enhancing_level
            + (tea.tea_enhancing ? 3 * dcm : 0)
            + (tea.tea_super_enhancing ? 6 * dcm : 0)
            + (tea.tea_ultra_enhancing ? 8 * dcm : 0);
        const levelBonus = Math.max(0, effectiveLevel - itemLevel);
        const equipBonus = playerParams.enhancers_top_speed + playerParams.enhancers_bottom_speed
            + playerParams.necklace_speed + playerParams.glove_bonus + (playerParams.chance_cape_speed || 0);
        const obsBonus = playerParams.laboratory_level;
        let teaSpeed = 0;
        if (tea.tea_enhancing) teaSpeed = 2;
        else if (tea.tea_super_enhancing) teaSpeed = 4;
        else if (tea.tea_ultra_enhancing) teaSpeed = 6;
        const communitySpeedBonus = Number(playerParams.community_enhancing_speed_bonus) || 0;
        const totalSpeedBonus = levelBonus + equipBonus + obsBonus + teaSpeed * dcm + communitySpeedBonus;
        return BASE_SPEED / (1 + totalSpeedBonus / 100);
    }

function calcEnhancingTimeSeconds(itemHrid, totalAttempts) {
        return totalAttempts * calcEnhancingSecondsPerAction(itemHrid);
    }

const MOONCAKE_PROFITABILITY_COLORS = MOONCAKE_DEFAULT_HOURLY_WAGE_COLOR_PROFILE.colors;

const MOONCAKE_PROFITABILITY_RANK = Object.freeze({
        loss: 0,
        red: 1,
        orange: 2,
        gold: 3,
        lightGreen: 4,
        brightGreen: 5
    });

const MOONCAKE_MARGIN_THRESHOLDS = Object.freeze({
        lowMid: Object.freeze({
            5: [0.03, 0.06, 0.10, 0.15],
            7: [0.03, 0.06, 0.10, 0.15],
            10: [0.02, 0.05, 0.08, 0.12],
            12: [0.02, 0.05, 0.08, 0.12]
        }),
        high: Object.freeze({
            5: [0.03, 0.06, 0.09, 0.12],
            7: [0.02, 0.04, 0.07, 0.10],
            10: [0.015, 0.03, 0.05, 0.08],
            12: [0.015, 0.03, 0.05, 0.08]
        })
    });

let mooncakeHourlyWageColorProfileCache = null;

function mooncakeNormalizeHourlyWageColorProfile(value, options = {}) {
        const strict = options.strict === true;
        const source = value && typeof value === 'object' ? value : {};
        const defaultThresholds = MOONCAKE_DEFAULT_HOURLY_WAGE_COLOR_PROFILE.thresholdsM;
        const rawThresholds = Array.isArray(source.thresholdsM) ? source.thresholdsM : null;
        if (strict && (!rawThresholds || rawThresholds.length !== defaultThresholds.length)) return null;
        const thresholdsM = defaultThresholds.map((fallback, index) => {
            const raw = rawThresholds?.[index];
            if (raw === undefined || raw === null || String(raw).trim() === '') {
                return strict ? NaN : fallback;
            }
            const parsed = Number(raw);
            if (!Number.isFinite(parsed) || parsed < 0 || parsed > MOONCAKE_HOURLY_WAGE_COLOR_PROFILE_MAX_M) {
                return strict ? NaN : fallback;
            }
            return Math.round(parsed * 1000) / 1000;
        });
        if (!thresholdsM.every(Number.isFinite) || thresholdsM.some((value, index) => index > 0 && value <= thresholdsM[index - 1])) {
            if (strict) return null;
            thresholdsM.splice(0, thresholdsM.length, ...defaultThresholds);
        }

        const rawColors = source.colors && typeof source.colors === 'object' ? source.colors : {};
        const colors = {};
        for (const key of MOONCAKE_HOURLY_WAGE_TIER_KEYS) {
            const fallback = MOONCAKE_PROFITABILITY_COLORS[key];
            const raw = String(rawColors[key] ?? '').trim();
            if (!raw) {
                if (strict) return null;
                colors[key] = fallback;
                continue;
            }
            if (!/^#[0-9a-fA-F]{6}$/.test(raw)) {
                if (strict) return null;
                colors[key] = fallback;
                continue;
            }
            colors[key] = raw.toUpperCase();
        }
        return {
            thresholdsM,
            thresholds: thresholdsM.map(value => value * 1e6),
            colors
        };
    }

function mooncakeGetHourlyWageColorProfile() {
        if (mooncakeHourlyWageColorProfileCache) return mooncakeHourlyWageColorProfileCache;
        mooncakeHourlyWageColorProfileCache = mooncakeNormalizeHourlyWageColorProfile(
            config.preferences?.hourlyWageColorProfile
        );
        return mooncakeHourlyWageColorProfileCache;
    }

function mooncakeGetProfitabilityEnhancementBucket(enhancementLevel) {
        const level = Math.max(0, Math.min(20, Math.floor(Number(enhancementLevel) || 0)));
        if (level <= 0) return 0;
        if (level <= 6) return 5;
        if (level <= 9) return 7;
        if (level <= 11) return 10;
        return 12;
    }

function mooncakeGetProfitabilityTier(value, thresholds) {
        if (!Number.isFinite(value)) return null;
        if (value <= 0) return 'loss';
        if (value < thresholds[0]) return 'red';
        if (value < thresholds[1]) return 'orange';
        if (value < thresholds[2]) return 'gold';
        if (value < thresholds[3]) return 'lightGreen';
        return 'brightGreen';
    }

function mooncakeGetHourlyWageTier(hourlyWage) {
        return mooncakeGetProfitabilityTier(Number(hourlyWage), mooncakeGetHourlyWageColorProfile().thresholds);
    }

function mooncakeGetProfitMarginTier(itemLevel, enhancementLevel, profitMargin) {
        const normalizedItemLevel = Number(itemLevel);
        const bucket = mooncakeGetProfitabilityEnhancementBucket(enhancementLevel);
        if (!(normalizedItemLevel > 0) || !bucket) return null;
        const marketTier = normalizedItemLevel >= 90 ? 'high' : 'lowMid';
        return mooncakeGetProfitabilityTier(profitMargin, MOONCAKE_MARGIN_THRESHOLDS[marketTier][bucket]);
    }

function mooncakeGetProfitabilityColor(tier, fallback = 'var(--color-disabled)') {
        return mooncakeGetHourlyWageColorProfile().colors[tier]
            || MOONCAKE_PROFITABILITY_COLORS[tier]
            || fallback;
    }

function mooncakeGetWorseProfitabilityTier(firstTier, secondTier) {
        if (!firstTier || !secondTier) return null;
        return MOONCAKE_PROFITABILITY_RANK[firstTier] <= MOONCAKE_PROFITABILITY_RANK[secondTier]
            ? firstTier
            : secondTier;
    }

function mooncakeEvaluateEnhancementEconomics({ itemHrid, itemLevel, enhancementLevel, sellPrice, totalCost, hourlyWage }) {
        const resolvedItemLevel = Number(itemLevel) > 0 ? Number(itemLevel) : getBaseItemLevel(itemHrid);
        const price = Number(sellPrice);
        const cost = Number(totalCost);
        const wage = Number(hourlyWage);
        if (!(resolvedItemLevel > 0) || mooncakeGetProfitabilityEnhancementBucket(enhancementLevel) <= 0 || !(price > 0) || !(cost > 0) || !Number.isFinite(wage)) {
            return null;
        }
        const profit = price * MOONCAKE_MARKET_SELL_NET_FACTOR - cost;
        const profitMargin = profit / cost;
        const hourlyTier = mooncakeGetHourlyWageTier(wage);
        const marginTier = mooncakeGetProfitMarginTier(resolvedItemLevel, enhancementLevel, profitMargin);
        const combinedTier = mooncakeGetWorseProfitabilityTier(hourlyTier, marginTier);
        return {
            itemLevel: resolvedItemLevel,
            profit,
            profitMargin,
            hourlyTier,
            marginTier,
            combinedTier,
            hourlyColor: mooncakeGetProfitabilityColor(hourlyTier),
            marginColor: mooncakeGetProfitabilityColor(marginTier),
            combinedColor: mooncakeGetProfitabilityColor(combinedTier)
        };
    }

function calcHourlyWageAndMetrics(itemHrid, enhancementLevel, marketData, price, options = {}) {
        if (price <= 0) return null;
        try {
            const route = mooncakeCalculateEnhancementRouteAtPrice(itemHrid, enhancementLevel, marketData, price);
            if (!route || !(route.totalCost > 0) || !(route.totalTimeHours > 0)) return null;
            const hourlyWage = route.hourlyWage;
            const routePair = options.includeRoutePair === false
                ? null
                : mooncakeResolveObjectiveRoutePair(
                    itemHrid,
                    enhancementLevel,
                    marketData,
                    price,
                    route
                );
            const metricsData = {
                ...route,
                hourlyWage,
                sellPrice: price,
                totalTimeHours: route.totalTimeHours,
                routePair
            };
            const evaluation = mooncakeEvaluateEnhancementEconomics({
                itemHrid,
                enhancementLevel,
                sellPrice: price,
                totalCost: metricsData.totalCost,
                hourlyWage
            });
            return {
                hourlyWage,
                evaluation,
                metrics: metricsData,
                routePair
            };
        } catch (err) {
            return null;
        }
    }

function mooncakeCalculateLevelZeroManufactureProfit(itemHrid, price, marketData, knownManufacturingCost) {
        const grossPrice = Number(price);
        if (!itemHrid || !(grossPrice > 0) || !marketData) return null;
        let manufacturingCost = 0;
        try {
            manufacturingCost = knownManufacturingCost === undefined
                ? Number(mooncakeGetConfiguredBaseItemCraftingCost(itemHrid, marketData))
                : Number(knownManufacturingCost);
        } catch (err) {
            console.warn('[MoonCake] +0 manufacture-profit calculation failed:', itemHrid, err);
            return null;
        }
        if (!(manufacturingCost > 0)) return null;
        const afterTaxRevenue = grossPrice * MOONCAKE_MARKET_SELL_NET_FACTOR;
        return {
            grossPrice,
            afterTaxRevenue,
            manufacturingCost,
            profit: afterTaxRevenue - manufacturingCost
        };
    }

function mooncakeCalculateLevelZeroMarketComparison(itemHrid, side, price, marketData) {
        const quotePrice = Number(price);
        if (!itemHrid || !(quotePrice > 0) || !marketData) return null;

        const normalizedSide = side === 'buy' ? 'buy' : 'sell';
        const baseResolution = mooncakeResolveGenericBaseItemPrice(itemHrid, marketData);
        const baseCost = Number(baseResolution?.price) || 0;
        const craftingCost = Number(baseResolution?.craftingCost) || 0;
        // A sell listing is something the player can buy now, so compare it
        // with crafting. A buy listing retains the configured lowest usable
        // acquisition baseline because it is not a direct buy-now decision.
        const comparisonCost = normalizedSide === 'sell' ? craftingCost : baseCost;
        const comparisonCostSource = normalizedSide === 'sell'
            ? 'craft'
            : baseResolution?.source || null;
        if (!(comparisonCost > 0)) return null;
        const manufacture = normalizedSide === 'sell'
            ? mooncakeCalculateLevelZeroManufactureProfit(
                itemHrid,
                quotePrice,
                marketData,
                craftingCost
            )
            : null;
        const purchaseSavings = comparisonCost - quotePrice;

        return {
            side: normalizedSide,
            quotePrice,
            afterTaxRevenue: normalizedSide === 'sell' ? manufacture?.afterTaxRevenue ?? null : null,
            baseItemCost: baseCost,
            comparisonCost,
            comparisonCostSource,
            baseItemSource: baseResolution?.source || null,
            craftingCost,
            readyMadeCost: Number(baseResolution?.productPrice) || 0,
            readyMadePriceSource: mooncakeGetBaseItemCostProductPriceSource(),
            directManufacturingCost: manufacture?.manufacturingCost ?? null,
            purchaseSavings,
            manufactureProfit: normalizedSide === 'sell' ? manufacture?.profit ?? null : null,
            comparisonValue: purchaseSavings
        };
    }

function mooncakeGetPositivePrice(value) {
        const price = Number(value);
        return Number.isFinite(price) && price > 0 ? price : 0;
    }

function mooncakeIsTraineeCharm(itemHrid) {
        return typeof itemHrid === 'string' &&
            itemHrid.startsWith('/items/trainee_') &&
            itemHrid.endsWith('_charm');
    }

function mooncakeGetMarketPriceObject(itemHRID, marketData) {
        if (!itemHRID || typeof itemHRID !== 'string' || !marketData?.marketData) return null;
        return marketData.marketData[itemHRID]?.['0'] || null;
    }

function mooncakeGetMarketAskPrice(itemHRID, marketData) {
        if (itemHRID === '/items/coin' || itemHRID === '/items/coins') return 1;
        if (!itemHRID || typeof itemHRID !== 'string') return 0;
        if (mooncakeIsTraineeCharm(itemHRID)) return 250000;
        return mooncakeGetPositivePrice(mooncakeGetMarketPriceObject(itemHRID, marketData)?.a);
    }

function mooncakeGetMarketBidPrice(itemHRID, marketData) {
        if (itemHRID === '/items/coin' || itemHRID === '/items/coins') return 1;
        if (!itemHRID || typeof itemHRID !== 'string') return 0;
        if (mooncakeIsTraineeCharm(itemHRID)) return 250000;
        return mooncakeGetPositivePrice(mooncakeGetMarketPriceObject(itemHRID, marketData)?.b);
    }

function getMarketPrice(itemHRID, marketData) {
        return mooncakeGetMarketAskPrice(itemHRID, marketData) ||
            mooncakeGetMarketBidPrice(itemHRID, marketData);
    }

function mooncakeIsFixedBaseItemCostPrice(itemHrid) {
        return itemHrid === '/items/coin' || itemHrid === '/items/coins' || mooncakeIsTraineeCharm(itemHrid);
    }

function mooncakeGetBaseItemCostPolicyQuote(itemHrid, marketData, source) {
        const normalizedSource = MOONCAKE_BASE_ITEM_COST_PRICE_SOURCE_KEYS.includes(source) ? source : null;
        if (!normalizedSource) return 0;

        // Coins and trainee charms already have an intentional fixed-cost
        // model. They can use either concrete market side, but not an invented
        // one-tick price above or below that fixed amount.
        if (mooncakeIsFixedBaseItemCostPrice(itemHrid) &&
            (normalizedSource === 'askMinusOne' || normalizedSource === 'bidPlusOne')) {
            return 0;
        }

        const ask = mooncakeGetMarketAskPrice(itemHrid, marketData);
        const bid = mooncakeGetMarketBidPrice(itemHrid, marketData);
        if (normalizedSource === 'ask') return ask;
        if (normalizedSource === 'bid') return bid;
        if (normalizedSource === 'askMinusOne') {
            if (!(ask > 0)) return 0;
            const stepped = getPriceTier(ask, 'down');
            return stepped > 0 && stepped < ask ? stepped : 0;
        }
        if (!(bid > 0)) return 0;
        const stepped = getPriceTier(bid, 'up');
        return stepped > bid ? stepped : 0;
    }

function mooncakeResolveMarketQuoteByPolicy(itemHrid, marketData, sourceOrder) {
        const orderedSources = mooncakeNormalizeBaseItemCostPriceSourceList(sourceOrder);
        for (const source of orderedSources) {
            const quote = mooncakeGetBaseItemCostPolicyQuote(itemHrid, marketData, source);
            if (quote > 0) return quote;
        }
        return 0;
    }

function mooncakeResolveCraftingContextMarketPrice(context, itemHrid, marketData, legacySide = 'market') {
        // The charm planner's market-base/fixed-upgrade branches have a
        // deliberate strict-left-one rule. Keep that existing special case;
        // normal recipe inputs below are governed by the selected policy.
        if (legacySide === 'ask') return mooncakeGetMarketAskPrice(itemHrid, marketData);
        if (typeof context?.resolveMaterialMarketPrice === 'function') {
            return context.resolveMaterialMarketPrice(itemHrid, marketData);
        }
        return getMarketPrice(itemHrid, marketData);
    }

function mooncakeCreateBaseItemCostCraftingContext(policy = mooncakeGetBaseItemCostPricePolicy()) {
        const materialSources = mooncakeNormalizeBaseItemCostPriceSourceList(policy?.material);
        return {
            memo: new Map(),
            artisanMultiplier: mooncakeGetArtisanMaterialMultiplier(),
            materialPriceSources: materialSources,
            resolveMaterialMarketPrice: (itemHrid, marketData) =>
                mooncakeResolveMarketQuoteByPolicy(itemHrid, marketData, materialSources)
        };
    }

function mooncakeGetConfiguredBaseItemCraftingCost(itemHrid, marketData, policy = mooncakeGetBaseItemCostPricePolicy()) {
        const materialSources = mooncakeNormalizeBaseItemCostPriceSourceList(policy?.material);
        if (!materialSources.length) return 0;
        return getCraftingCost(
            itemHrid,
            marketData,
            new Set(),
            mooncakeCreateBaseItemCostCraftingContext({ ...policy, material: materialSources })
        );
    }

function mooncakeGetBaseItemCostResolutionCacheKey(itemHrid, policy) {
        const artisanMultiplier = mooncakeGetArtisanMaterialMultiplier();
        return [
            mooncakeMarketPricingRevision,
            mooncakeCharacterCalcSignature || 'live',
            Number.isFinite(artisanMultiplier) ? artisanMultiplier.toFixed(12) : 'default',
            policy.material.join(','),
            policy.product,
            itemHrid
        ].join('|');
    }

function mooncakeGetBaseItemCostResolutionCache(marketData) {
        if (!marketData || (typeof marketData !== 'object' && typeof marketData !== 'function')) return null;
        let cache = mooncakeBaseItemCostResolutionCaches.get(marketData);
        if (!cache) {
            cache = new Map();
            mooncakeBaseItemCostResolutionCaches.set(marketData, cache);
        }
        return cache;
    }

function mooncakeGetArtisanMaterialMultiplier() {
        const concentration = Math.max(0, Number(getDrinkConcentrationBonus()) || 0);
        // 工匠茶基础减耗始终生效，暴饮之囊只放大这 10% 效果。
        return Math.max(0, 1 - 0.1 * (1 + concentration / 100));
    }

function mooncakeGetRecipeMaterialMultiplier(itemHrid, artisanMultiplier) {
        // 大师、宗师护符材料昂贵且制作次数有限，按完整材料投入计价，
        // 不把工匠茶和暴饮之囊的期望减耗折算进本层配方。
        if (/^\/items\/(?:master|grandmaster)_.+_charm$/.test(itemHrid)) return 1;
        return Number.isFinite(artisanMultiplier)
            ? artisanMultiplier
            : mooncakeGetArtisanMaterialMultiplier();
    }

function mooncakeGetCharmPreviousTierHrid(itemHrid) {
        const match = /^\/items\/(basic|advanced|expert|master|grandmaster)_(.+)_charm$/.exec(itemHrid);
        if (!match) return null;
        const previousTier = {
            basic: 'trainee',
            advanced: 'basic',
            expert: 'advanced',
            master: 'expert',
            grandmaster: 'master'
        }[match[1]];
        return previousTier ? `/items/${previousTier}_${match[2]}_charm` : null;
    }

function mooncakeIsCharmUpgradeInput(itemHrid, inputHrid) {
        // Charm actions may expose the previous tier through upgradeItemHrid or
        // directly inside inputItems. Derive it from the HRID so fixed and
        // normal inputs can follow their distinct cost rules.
        return inputHrid === mooncakeGetCharmPreviousTierHrid(itemHrid);
    }

function mooncakeIsCharmTier(itemHrid) {
        return typeof itemHrid === 'string' &&
            /^\/items\/(?:basic|advanced|expert|master|grandmaster)_.+_charm$/.test(itemHrid);
    }

function mooncakeIsCraftableCharmTier(itemHrid, costContext = null) {
        return Boolean(mooncakeGetCharmCraftingRecipe(itemHrid, costContext));
    }

function mooncakeGetCharmTierRank(itemHrid) {
        const match = /^\/items\/(basic|advanced|expert|master|grandmaster)_.+_charm$/.exec(itemHrid || '');
        if (!match) return -1;
        return {
            basic: 1,
            advanced: 2,
            expert: 3,
            master: 4,
            grandmaster: 5
        }[match[1]] || -1;
    }

function mooncakeChooseLowerPositiveCost(first, second) {
        const choices = [first, second].filter(value => Number.isFinite(value) && value > 0);
        return choices.length ? Math.min(...choices) : 0;
    }

function mooncakeEnsureCharmPlanContext(costContext) {
        const context = costContext || {
            memo: new Map(),
            artisanMultiplier: mooncakeGetArtisanMaterialMultiplier()
        };
        if (!(context.memo instanceof Map)) context.memo = new Map();
        if (!(context.charmRecipeMemo instanceof Map)) context.charmRecipeMemo = new Map();
        if (!(context.charmPureMemo instanceof Map)) context.charmPureMemo = new Map();
        if (!(context.charmDemandMemo instanceof Map)) context.charmDemandMemo = new Map();
        if (!(context.charmPlanMemo instanceof Map)) context.charmPlanMemo = new Map();
        if (!(context.charmPlanBuilding instanceof Set)) context.charmPlanBuilding = new Set();
        if (!Number.isFinite(context.artisanMultiplier)) {
            context.artisanMultiplier = mooncakeGetArtisanMaterialMultiplier();
        }
        return context;
    }

function mooncakeGetCharmCraftingRecipe(itemHrid, costContext = null) {
        if (!mooncakeIsCharmTier(itemHrid)) return null;

        const context = costContext ? mooncakeEnsureCharmPlanContext(costContext) : null;
        if (context?.charmRecipeMemo?.has(itemHrid)) {
            return context.charmRecipeMemo.get(itemHrid);
        }

        const recipe = getCraftingRecipe(itemHrid);
        const craftingRecipe = recipe?.inputs?.length ? recipe : null;
        if (context) context.charmRecipeMemo.set(itemHrid, craftingRecipe);
        return craftingRecipe;
    }

function mooncakeIsMarketBaseCharm(itemHrid, costContext = null) {
        return mooncakeIsCharmTier(itemHrid) &&
            !mooncakeIsCraftableCharmTier(itemHrid, costContext);
    }

function mooncakeCloneCharmDemand(demand) {
        return demand instanceof Map ? new Map(demand) : new Map();
    }

function mooncakeAddCharmDemand(target, source, multiplier = 1) {
        if (!(target instanceof Map) || !(source instanceof Map) || !(multiplier > 0)) return;
        for (const [itemHrid, quantity] of source) {
            const adjustedQuantity = Number(quantity) * multiplier;
            if (!(adjustedQuantity > 0)) continue;
            target.set(itemHrid, (Number(target.get(itemHrid)) || 0) + adjustedQuantity);
        }
    }

function mooncakeGetPureCharmCraftCost(itemHrid, marketData, processedItems = new Set(), costContext = null) {
        if (!mooncakeIsCharmTier(itemHrid) || processedItems.has(itemHrid)) return 0;

        const context = mooncakeEnsureCharmPlanContext(costContext);
        if (context.charmPureMemo.has(itemHrid)) return context.charmPureMemo.get(itemHrid);

        const rememberCost = value => {
            const cost = Number.isFinite(value) && value > 0 ? value : 0;
            context.charmPureMemo.set(itemHrid, cost);
            return cost;
        };
        const recipe = mooncakeGetCharmCraftingRecipe(itemHrid, context);
        if (!recipe) return rememberCost(0);

        const nextProcessedItems = new Set(processedItems);
        nextProcessedItems.add(itemHrid);
        const recipeMaterialMultiplier = mooncakeGetRecipeMaterialMultiplier(
            itemHrid,
            context.artisanMultiplier
        );
        let totalCost = 0;

        for (const input of recipe.inputs) {
            const count = Number(input?.count);
            if (!input?.itemHrid || !(count > 0)) return rememberCost(0);

            const inputHrid = input.itemHrid;
            const isFixedUpgradeItem = input.isFixedUpgradeItem === true;
            const adjustedCount = isFixedUpgradeItem ? count : count * recipeMaterialMultiplier;
            let unitCost = 0;

            if (mooncakeIsCharmTier(inputHrid)) {
                unitCost = mooncakeIsCraftableCharmTier(inputHrid, context)
                    ? mooncakeGetPureCharmCraftCost(
                        inputHrid,
                        marketData,
                        nextProcessedItems,
                        context
                    )
                    : mooncakeResolveCraftingContextMarketPrice(context, inputHrid, marketData, 'ask');
            } else {
                const marketPrice = mooncakeResolveCraftingContextMarketPrice(context, inputHrid, marketData);
                const needsCraftComparison = itemHrid.includes('_refined') || !(marketPrice > 0);
                const craftingCost = needsCraftComparison
                    ? getCraftingCost(inputHrid, marketData, nextProcessedItems, context)
                    : 0;
                unitCost = itemHrid.includes('_refined')
                    ? mooncakeChooseLowerPositiveCost(marketPrice, craftingCost)
                    : (marketPrice > 0 ? marketPrice : craftingCost);
            }

            if (!(unitCost > 0) || !(adjustedCount > 0)) return rememberCost(0);
            totalCost += unitCost * adjustedCount;
        }

        const outputCount = Math.max(1, Number(recipe.outputCount) || 1);
        return rememberCost(totalCost / outputCount);
    }

function mooncakeGetPureCharmDemand(itemHrid, processedItems = new Set(), costContext = null) {
        if (!mooncakeIsCharmTier(itemHrid) || processedItems.has(itemHrid)) return null;

        const context = mooncakeEnsureCharmPlanContext(costContext);
        if (context.charmDemandMemo.has(itemHrid)) {
            return mooncakeCloneCharmDemand(context.charmDemandMemo.get(itemHrid));
        }

        const recipe = mooncakeGetCharmCraftingRecipe(itemHrid, context);
        const demand = new Map([[itemHrid, 1]]);
        if (!recipe) {
            context.charmDemandMemo.set(itemHrid, mooncakeCloneCharmDemand(demand));
            return demand;
        }

        const nextProcessedItems = new Set(processedItems);
        nextProcessedItems.add(itemHrid);
        const outputCount = Math.max(1, Number(recipe.outputCount) || 1);
        const recipeMaterialMultiplier = mooncakeGetRecipeMaterialMultiplier(
            itemHrid,
            context.artisanMultiplier
        );

        for (const input of recipe.inputs) {
            const count = Number(input?.count);
            if (!input?.itemHrid || !(count > 0)) return null;
            if (!mooncakeIsCharmTier(input.itemHrid)) continue;

            const adjustedCount = (input.isFixedUpgradeItem === true ? count : count * recipeMaterialMultiplier) /
                outputCount;
            const childDemand = mooncakeGetPureCharmDemand(input.itemHrid, nextProcessedItems, context);
            if (!childDemand || !(adjustedCount > 0)) return null;
            mooncakeAddCharmDemand(demand, childDemand, adjustedCount);
        }

        context.charmDemandMemo.set(itemHrid, mooncakeCloneCharmDemand(demand));
        return demand;
    }

function mooncakeBuildCharmCraftingPlan(itemHrid, marketData, costContext = null) {
        if (!mooncakeIsCharmTier(itemHrid)) return null;

        const context = mooncakeEnsureCharmPlanContext(costContext);
        if (!mooncakeGetCharmCraftingRecipe(itemHrid, context)) return null;
        if (context.charmPlanMemo.has(itemHrid)) return context.charmPlanMemo.get(itemHrid);
        if (context.charmPlanBuilding.has(itemHrid)) return null;

        context.charmPlanBuilding.add(itemHrid);
        try {
            const pureCost = mooncakeGetPureCharmCraftCost(itemHrid, marketData, new Set(), context);
            const fullDemand = mooncakeGetPureCharmDemand(itemHrid, new Set(), context);
            if (!(pureCost > 0) || !fullDemand) {
                const emptyPlan = {
                    pureCost: 0,
                    totalCost: 0,
                    totalSaving: 0,
                    pureCostsByHrid: new Map(),
                    purchases: [],
                    marketBasePurchases: [],
                    purchaseByHrid: new Map()
                };
                context.charmPlanMemo.set(itemHrid, emptyPlan);
                return emptyPlan;
            }

            const pureCostsByHrid = new Map();
            const marketBasePurchases = [];
            const candidates = [];
            for (const [candidateHrid, quantity] of fullDemand) {
                if (candidateHrid === itemHrid || !(quantity > 0)) {
                    continue;
                }
                if (!mooncakeIsCraftableCharmTier(candidateHrid, context)) {
                    const marketAsk = mooncakeResolveCraftingContextMarketPrice(context, candidateHrid, marketData, 'ask');
                    if (marketAsk > 0) {
                        marketBasePurchases.push({
                            itemHrid: candidateHrid,
                            price: marketAsk,
                            quantity
                        });
                    }
                    continue;
                }
                const pureUnitCost = mooncakeGetPureCharmCraftCost(candidateHrid, marketData, new Set(), context);
                pureCostsByHrid.set(candidateHrid, pureUnitCost);
                const marketAsk = mooncakeResolveCraftingContextMarketPrice(context, candidateHrid, marketData, 'ask');
                if (marketAsk > 0 && pureUnitCost > 0 && marketAsk < pureUnitCost) {
                    candidates.push({
                        itemHrid: candidateHrid,
                        marketAsk,
                        pureUnitCost,
                        rank: mooncakeGetCharmTierRank(candidateHrid)
                    });
                }
            }
            pureCostsByHrid.set(itemHrid, pureCost);
            candidates.sort((left, right) => right.rank - left.rank || left.itemHrid.localeCompare(right.itemHrid));

            let best = { totalSaving: 0, purchases: [] };
            const combinationCount = 1 << candidates.length;
            const epsilon = 1e-7;
            for (let mask = 1; mask < combinationCount; mask++) {
                const residualDemand = mooncakeCloneCharmDemand(fullDemand);
                const purchases = [];
                let totalSaving = 0;
                let valid = true;

                // High-tier purchases are applied first. They remove their own
                // lower-tier self-crafting tree before any lower-tier purchase
                // is considered, so one listing can never be reused.
                for (let index = 0; index < candidates.length; index++) {
                    if (!(mask & (1 << index))) continue;
                    const candidate = candidates[index];
                    const availableQuantity = Number(residualDemand.get(candidate.itemHrid)) || 0;
                    if (!(availableQuantity > epsilon)) {
                        valid = false;
                        break;
                    }
                    const replacementQuantity = Math.min(1, availableQuantity);
                    const replacementDemand = mooncakeGetPureCharmDemand(
                        candidate.itemHrid,
                        new Set(),
                        context
                    );
                    if (!replacementDemand) {
                        valid = false;
                        break;
                    }
                    for (const [requiredHrid, requiredQuantity] of replacementDemand) {
                        const remaining = (Number(residualDemand.get(requiredHrid)) || 0) -
                            Number(requiredQuantity) * replacementQuantity;
                        residualDemand.set(requiredHrid, Math.abs(remaining) < epsilon ? 0 : remaining);
                    }
                    const saving = (candidate.pureUnitCost - candidate.marketAsk) * replacementQuantity;
                    totalSaving += saving;
                    purchases.push({
                        itemHrid: candidate.itemHrid,
                        price: candidate.marketAsk,
                        marketAsk: candidate.marketAsk,
                        pureUnitCost: candidate.pureUnitCost,
                        quantity: replacementQuantity,
                        saving
                    });
                }

                if (valid && totalSaving > best.totalSaving + epsilon) {
                    best = { totalSaving, purchases };
                }
            }

            const purchases = best.purchases;
            const plan = {
                pureCost,
                totalCost: Math.max(0, pureCost - best.totalSaving),
                totalSaving: best.totalSaving,
                pureCostsByHrid,
                purchases,
                marketBasePurchases,
                purchaseByHrid: new Map(purchases.map(purchase => [purchase.itemHrid, purchase]))
            };
            context.charmPlanMemo.set(itemHrid, plan);
            return plan;
        } finally {
            context.charmPlanBuilding.delete(itemHrid);
        }
    }

function mooncakeResolveCharmUpgradeInputCost(itemHrid, input, marketData, processedItems, costContext) {
        const inputHrid = input?.itemHrid;
        if (!mooncakeIsCharmUpgradeInput(itemHrid, inputHrid)) return null;

        const context = mooncakeEnsureCharmPlanContext(costContext);
        const isFixedUpgradeItem = input?.isFixedUpgradeItem === true;
        const hasCraftingRecipe = mooncakeIsCraftableCharmTier(inputHrid, context);
        const isMarketBaseCharm = mooncakeIsMarketBaseCharm(inputHrid, context);
        const marketAsk = mooncakeResolveCraftingContextMarketPrice(context, inputHrid, marketData, 'ask');
        const craftingCost = hasCraftingRecipe
            ? mooncakeGetPureCharmCraftCost(inputHrid, marketData, processedItems, context)
            : (isMarketBaseCharm
                ? marketAsk
                : (mooncakeIsTraineeCharm(inputHrid)
                ? marketAsk
                : getCraftingCost(inputHrid, marketData, processedItems, context)));
        const plan = mooncakeIsCraftableCharmTier(itemHrid, context)
            ? mooncakeBuildCharmCraftingPlan(itemHrid, marketData, context)
            : null;
        const selectedPurchase = isFixedUpgradeItem
            ? plan?.purchaseByHrid?.get(inputHrid)
            : null;
        const useMarket = selectedPurchase && selectedPurchase.quantity > 0;
        const price = useMarket ? selectedPurchase.price : craftingCost;

        return {
            price,
            source: useMarket ? 'market' : (isMarketBaseCharm
                ? 'marketBase'
                : (mooncakeIsTraineeCharm(inputHrid) ? 'base' : (craftingCost > 0 ? 'craft' : null))),
            marketAsk,
            craftingCost,
            isMarketBaseCharm,
            isCheapMarketPurchase: Boolean(useMarket && craftingCost > 0 && price < craftingCost)
        };
    }

function getCraftingRecipe(itemHrid) {
        if (!itemHrid || typeof itemHrid !== 'string') return null;
        const initData = getInitClientData();
        if (!initData) return null;

        const itemName = itemHrid.split('/').pop() || '';

        const shopHrid = `/shop_items/${itemName}`;
        if (initData.shopItemDetailMap?.hasOwnProperty(shopHrid)) {
            const shopItemDetail = initData.shopItemDetailMap[shopHrid];
            if (shopItemDetail.category === "/shop_categories/dungeon") {
                const recipe = { inputs: [], outputCount: 1 };
                shopItemDetail.costs.forEach(cost => {
                    recipe.inputs.push({ itemHrid: cost.itemHrid, count: cost.count });
                });
                return recipe;
            }
        }

        const actionTypes = ["cheesesmithing", "crafting", "tailoring", "cooking", "brewing"];
        for (const actionType of actionTypes) {
            const actionHrid = `/actions/${actionType}/${itemName}`;
            if (initData.actionDetailMap?.hasOwnProperty(actionHrid)) {
                const actionDetail = initData.actionDetailMap[actionHrid];
                const recipe = { inputs: [], outputCount: 1, upgradeItemHrid: actionDetail.upgradeItemHrid };

                if (actionDetail.upgradeItemHrid) {
                    // Keep the source, not only the HRID. An action can consume one
                    // fixed upgrade item plus more copies of that item as materials.
                    recipe.inputs.push({
                        itemHrid: actionDetail.upgradeItemHrid,
                        count: 1,
                        isFixedUpgradeItem: true
                    });
                }

                if (actionDetail.inputItems) {
                    actionDetail.inputItems.forEach(input => {
                        recipe.inputs.push({
                            itemHrid: input.itemHrid,
                            count: input.count,
                            isFixedUpgradeItem: false
                        });
                    });
                }

                if (actionDetail.outputItems && actionDetail.outputItems.length > 0) {
                    const matching = actionDetail.outputItems.find(o => o.itemHrid === itemHrid);
                    if (matching) {
                        recipe.outputCount = matching.count || 1;
                    }
                }

                return recipe;
            }
        }
        return null;
    }

function getCraftingCost(itemHrid, marketData, processedItems = new Set(), costContext = null) {
        try {
            if (!itemHrid || processedItems.has(itemHrid)) return 0;

            const context = costContext || {
                memo: new Map(),
                artisanMultiplier: mooncakeGetArtisanMaterialMultiplier()
            };
            if (context.memo.has(itemHrid)) return context.memo.get(itemHrid);

            const rememberCost = value => {
                const cost = Number.isFinite(value) && value > 0 ? value : 0;
                context.memo.set(itemHrid, cost);
                return cost;
            };

            // Charm plans keep pure recursive cost separate from the limited
            // once-only market substitutions. Do this before generic recipe
            // traversal so discounted child costs are never multiplied.
            if (mooncakeIsCraftableCharmTier(itemHrid, context) && !context.skipCharmPlan) {
                const charmPlan = mooncakeBuildCharmCraftingPlan(itemHrid, marketData, context);
                return rememberCost(charmPlan?.totalCost || 0);
            }

            const nextProcessedItems = new Set(processedItems);
            nextProcessedItems.add(itemHrid);

            const recipe = getCraftingRecipe(itemHrid);
            if (!recipe?.inputs?.length) return rememberCost(0);

            const recipeMaterialMultiplier = mooncakeGetRecipeMaterialMultiplier(
                itemHrid,
                context.artisanMultiplier
            );
            let totalCost = 0;
            for (const input of recipe.inputs) {
                const count = Number(input?.count);
                if (!input?.itemHrid || !(count > 0)) return rememberCost(0);

                const isFixedUpgradeItem = input.isFixedUpgradeItem === true;
                let price = 0;
                const charmUpgradeCost = mooncakeResolveCharmUpgradeInputCost(
                    itemHrid,
                    input,
                    marketData,
                    nextProcessedItems,
                    context
                );

                if (charmUpgradeCost) {
                    price = charmUpgradeCost.price;
                } else {
                    const marketPrice = mooncakeResolveCraftingContextMarketPrice(context, input.itemHrid, marketData);
                    const needsCraftComparison = itemHrid.includes('_refined') || !(marketPrice > 0);
                    const craftingCost = needsCraftComparison
                        ? getCraftingCost(input.itemHrid, marketData, nextProcessedItems, context)
                        : 0;

                    if (itemHrid.includes('_refined')) {
                        price = mooncakeChooseLowerPositiveCost(marketPrice, craftingCost);
                    } else {
                        price = marketPrice > 0 ? marketPrice : craftingCost;
                    }
                }

                // A missing input must invalidate the recipe rather than silently
                // treating that material as free.
                if (!(price > 0)) return rememberCost(0);

                // upgradeItemHrid 是固定消耗，不受工匠茶效果影响
                // 其他材料受工匠茶和暴饮之囊效果影响。
                // A duplicate of the upgrade HRID inside inputItems is still a normal
                // material and must receive the recipe's tea/drink reduction.
                const adjustedCount = isFixedUpgradeItem ? count : count * recipeMaterialMultiplier;
                totalCost += price * adjustedCount;
            }

            const outputCount = Math.max(1, Number(recipe.outputCount) || 1);
            return rememberCost(totalCost / outputCount);
        } catch (err) {
            console.error('[Better Loot Tracker] 计算制造成本时出错:', itemHrid, err);
            return 0;
        }
    }

const SUCCESS_RATE = [
        50, 45, 45, 40, 40, 40, 35, 35, 35, 35,
        30, 30, 30, 30, 30, 30, 30, 30, 30, 30
    ];

const ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP = {
        0: 0, 1: 2, 2: 4.2, 3: 6.6, 4: 9.2, 5: 12, 6: 15, 7: 18.2, 8: 21.6, 9: 25.2, 10: 29,
        11: 33.4, 12: 38.4, 13: 44, 14: 50.2, 15: 57, 16: 64.4, 17: 72.4, 18: 81, 19: 90.2, 20: 100
    };

const ENHANCE_DEFAULT_PARAMS = {
        enhancing_level: 125,
        laboratory_level: 6,
        enhancer_bonus: 5.42,
        glove_bonus: 12.9,
        community_enhancing_speed_level: 0,
        community_enhancing_speed_bonus: 0,
        tea_enhancing: false,
        tea_super_enhancing: false,
        tea_ultra_enhancing: true,
        tea_blessed: true
    };

const ENHANCE_NEUTRAL_PARAMS = {
        enhancing_level: 0,
        laboratory_level: 0,
        enhancer_bonus: 0,
        glove_bonus: 0,
        community_enhancing_speed_level: 0,
        community_enhancing_speed_bonus: 0,
        tea_enhancing: false,
        tea_super_enhancing: false,
        tea_ultra_enhancing: false,
        tea_blessed: false,
        champion_achievement: false
    };

function getBaseItemLevel(itemHRID) {
        if (!mooncakeEnsureItemDetailMap()) return 0;
        const itemDetails = itemDetailMap[itemHRID];
        return itemDetails?.itemLevel || 0;
    }

function getEnhancementCosts(itemHRID) {
        if (!mooncakeEnsureItemDetailMap()) return null;

        const itemData = itemDetailMap[itemHRID];
        if (!itemData?.enhancementCosts) return null;

        return itemData.enhancementCosts;
    }

function getProtectionItems(itemHRID) {
        if (!mooncakeEnsureItemDetailMap()) return [itemHRID, "/items/mirror_of_protection"];

        const itemData = itemDetailMap[itemHRID];
        let protectHrids = [itemHRID, "/items/mirror_of_protection"];

        if (itemData?.protectionItemHrids) {
            protectHrids = protectHrids.concat(itemData.protectionItemHrids);
        }

        return protectHrids;
    }

let mooncakePlayerEnhanceParamsCacheKey = '';

let mooncakePlayerEnhanceParamsCacheItemDetailMap = null;

let mooncakePlayerEnhanceParamsCache = null;

let mooncakeEnhancementParamsOverride = null;

function mooncakeCollectionValues(value) {
        if (Array.isArray(value)) return value.filter(Boolean);
        if (value instanceof Map) return Array.from(value.values()).filter(Boolean);
        if (value && typeof value === 'object') return Object.values(value).filter(Boolean);
        return [];
    }

function mooncakeCollectionEntries(value) {
        if (value instanceof Map) return Array.from(value.entries());
        if (Array.isArray(value)) return value.map((entry, index) => [String(index), entry]);
        if (value && typeof value === 'object') return Object.entries(value);
        return [];
    }

function mooncakeGetMapEntry(value, key) {
        if (value instanceof Map) return value.get(key);
        return value && typeof value === 'object' ? value[key] : undefined;
    }

function mooncakeRelevantCharacterItems(value) {
        return mooncakeCollectionValues(value).filter(item =>
            item?.itemLocationHrid &&
            item.itemLocationHrid !== '/item_locations/inventory' &&
            Number(item.count ?? 1) !== 0
        );
    }

function mooncakeCollectItemHrids(value, result = new Set(), seen = new WeakSet(), depth = 0) {
        if (value == null || depth > 5) return result;
        if (typeof value === 'string') {
            if (value.startsWith('/items/')) result.add(value);
            return result;
        }
        if (typeof value !== 'object') return result;
        if (seen.has(value)) return result;
        seen.add(value);
        const values = value instanceof Map
            ? Array.from(value.values())
            : (Array.isArray(value) ? value : Object.values(value));
        values.forEach(entry => mooncakeCollectItemHrids(entry, result, seen, depth + 1));
        return result;
    }

function mooncakeGetEnhancingDrinkHrids() {
        const slots = mooncakeGetMapEntry(characterActionTypeDrinkSlotsMap, MOONCAKE_ENHANCING_ACTION_TYPE_HRID);
        return [...mooncakeCollectItemHrids(slots)].sort();
    }

function mooncakeGetAchievementTierState(tierHrid) {
        const buffsByAction = characterAchievementActionTypeBuffsMap;
        if (!buffsByAction || typeof buffsByAction !== 'object') return null;
        if (typeof tierHrid !== 'string') return false;
        const tier = tierHrid.replace(/^\/achievement_tiers\//, '');
        if (!tier) return false;
        const uniquePrefix = `/buff_uniques/achievement_${tier}_`;
        for (const [, buffs] of mooncakeCollectionEntries(buffsByAction)) {
            for (const buff of mooncakeCollectionValues(buffs)) {
                if (typeof buff?.uniqueHrid === 'string' && buff.uniqueHrid.startsWith(uniquePrefix)) {
                    return true;
                }
            }
        }
        return false;
    }

function mooncakeHasChampionAchievement() {
        return mooncakeGetAchievementTierState('/achievement_tiers/champion') === true;
    }

function mooncakeGetEnhancingTeaParams() {
        const result = {
            tea_enhancing: false,
            tea_super_enhancing: false,
            tea_ultra_enhancing: false,
            tea_blessed: false
        };
        for (const itemHrid of mooncakeGetEnhancingDrinkHrids()) {
            if (itemHrid === '/items/enhancing_tea') result.tea_enhancing = true;
            if (itemHrid === '/items/super_enhancing_tea') result.tea_super_enhancing = true;
            if (itemHrid === '/items/ultra_enhancing_tea') result.tea_ultra_enhancing = true;
            if (itemHrid === '/items/blessed_tea') result.tea_blessed = true;

            const buffs = itemDetailMap?.[itemHrid]?.consumableDetail?.buffs;
            if (!Array.isArray(buffs)) continue;
            for (const buff of buffs) {
                if (buff?.typeHrid === '/buff_types/blessed' && Number(buff.flatBoost) > 0) {
                    result.tea_blessed = true;
                }
                if (buff?.typeHrid !== '/buff_types/enhancing_level') continue;
                const levelBoost = Number(buff.flatBoost) || 0;
                if (levelBoost >= 8) result.tea_ultra_enhancing = true;
                else if (levelBoost >= 6) result.tea_super_enhancing = true;
                else if (levelBoost > 0) result.tea_enhancing = true;
            }
        }
        return result;
    }

function getDrinkConcentrationBonus() {
        // 检查是否启用了虚拟配置
        if (config.virtual.enabled) {
            // 计算虚拟的饮品浓度加成
            const calculateDrinkConcentrationBonus = (level) => {
                if (level === -1) {
                    return 0;
                }
                const getDrinkConcentrationBase = () => {
                    const itemDetail = itemDetailMap?.['/items/guzzling_pouch'];
                    return itemDetail?.equipmentDetail?.noncombatStats?.drinkConcentration || 0.05;
                };
                const baseBonus = getDrinkConcentrationBase();
                const enhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[level] || 0) / 100;
                return baseBonus * enhanceBonus * 100;
            };
            return calculateDrinkConcentrationBonus(config.virtual.drink_pouch_level);
        }

        // 否则使用实际装备的加成
        mooncakeEnsureCharacterData();
        if (!characterItems || !itemDetailMap) return 0;

        for (const item of mooncakeRelevantCharacterItems(characterItems)) {
            if (item.itemLocationHrid === "/item_locations/pouch" && item.itemHrid === "/items/guzzling_pouch") {
                const itemDetail = itemDetailMap[item.itemHrid];

                if (itemDetail?.equipmentDetail?.noncombatStats?.drinkConcentration) {
                    const enhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[item.enhancementLevel || 0] || 0) / 100;
                    const result = itemDetail?.equipmentDetail?.noncombatStats?.drinkConcentration * enhanceBonus * 100;
                    return result;
                }
            }
        }
        return 0;
    }

function getPlayerEnhanceParams() {
        try {
            if (mooncakeEnhancementParamsOverride) return mooncakeEnhancementParamsOverride;
            if (!config.virtual.enabled) mooncakeEnsureCharacterData();
            const communityEnhancingSpeedLevel = mooncakeGetEffectiveEnhancingCommunityBuffLevel();
            const communityEnhancingSpeedBonus = mooncakeGetCommunityEnhancingSpeedBonusForLevel(communityEnhancingSpeedLevel);
            const cacheKey = config.virtual.enabled
                ? `virtual:${JSON.stringify(config.virtual)}:community:${communityEnhancingSpeedLevel}:${mooncakeIsEnhancingCommunityBuffEnabled()}`
                : `character:${mooncakeCharacterCalcSignature || mooncakeBuildCharacterCalcSignature()}:community:${communityEnhancingSpeedLevel}:${mooncakeIsEnhancingCommunityBuffEnabled()}`;
            if (mooncakePlayerEnhanceParamsCache &&
                mooncakePlayerEnhanceParamsCacheKey === cacheKey &&
                mooncakePlayerEnhanceParamsCacheItemDetailMap === itemDetailMap) {
                return mooncakePlayerEnhanceParamsCache;
            }
            const cacheResult = (params) => {
                mooncakePlayerEnhanceParamsCacheKey = cacheKey;
                mooncakePlayerEnhanceParamsCacheItemDetailMap = itemDetailMap;
                mooncakePlayerEnhanceParamsCache = params;
                return params;
            };

            // 检查是否启用了虚拟配置
            if (config.virtual.enabled) {
                // 从itemDetailMap获取装备的基础属性
                const getEnhancerTopBaseSpeed = () => {
                    const itemDetail = itemDetailMap?.['/items/enhancers_top'];
                    return itemDetail?.equipmentDetail?.noncombatStats?.enhancingSpeed || 0.5;
                };

                const getEnhancerBottomBaseSpeed = () => {
                    const itemDetail = itemDetailMap?.['/items/enhancers_bottoms'];
                    return itemDetail?.equipmentDetail?.noncombatStats?.enhancingSpeed || 0.5;
                };

                const getNecklaceBaseSpeed = () => {
                    // 优先使用哲学家项链，其次使用速度项链
                    const philosopherNecklace = itemDetailMap?.['/items/philosophers_necklace'];
                    const speedNecklace = itemDetailMap?.['/items/necklace_of_speed'];
                    return (philosopherNecklace?.equipmentDetail?.noncombatStats?.skillingSpeed ||
                            speedNecklace?.equipmentDetail?.noncombatStats?.skillingSpeed) || 0.3;
                };

                const getGloveBaseBonus = () => {
                    // 查找手套的基础属性
                    for (const key in itemDetailMap) {
                        if (key.includes('glove') || key.includes('gloves') || key.includes('gauntlets')) {
                            const itemDetail = itemDetailMap[key];
                            if (itemDetail?.equipmentDetail?.noncombatStats?.enhancingSpeed) {
                                return itemDetail?.equipmentDetail?.noncombatStats?.enhancingSpeed;
                            }
                        }
                    }
                    return 0.1;
                };

                const getChanceCapeBaseSpeed = (type) => {
                    if (type === 'none') {
                        return 0;
                    }
                    const itemDetail = itemDetailMap?.[type === 'refined' ? '/items/chance_cape_refined' : '/items/chance_cape'];
                    return itemDetail?.equipmentDetail?.noncombatStats?.enhancingSpeed || 0.05;
                };

                const getDrinkConcentrationBase = () => {
                    const itemDetail = itemDetailMap?.['/items/guzzling_pouch'];
                    return itemDetail?.equipmentDetail?.noncombatStats?.drinkConcentration || 0.05;
                };

                const calculateEnhancerBonus = (type, level) => {
                const enhancerHrid = type === 'divine' ? '/items/holy_enhancer' : '/items/celestial_enhancer';
                const itemDetail = itemDetailMap?.[enhancerHrid];
                if (!itemDetail?.equipmentDetail?.noncombatStats?.enhancingSuccess) {
                    return 0;
                }

                const baseFraction = itemDetail?.equipmentDetail?.noncombatStats?.enhancingSuccess || 0.0;
                if (level >= 1) {
                    const instanceLevel = Math.min(Math.max(level, 0), 20);
                    const multiplier = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[instanceLevel] || 0) / 100.0;
                    const finalFraction = baseFraction * multiplier;
                    return Number((finalFraction * 100).toFixed(4));
                } else {
                    return Number((baseFraction * 100).toFixed(4));
                }
            };

            // 根据装备等级计算相应的速度和加成
            const calculateEnhancerTopSpeed = (level) => {
                if (level === -1) {
                    return 0;
                }
                const baseSpeed = getEnhancerTopBaseSpeed();
                const enhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[level] || 0) / 100;
                return baseSpeed * enhanceBonus * 100;
            };

            const calculateEnhancerBottomSpeed = (level) => {
                if (level === -1) {
                    return 0;
                }
                const baseSpeed = getEnhancerBottomBaseSpeed();
                const enhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[level] || 0) / 100;
                return baseSpeed * enhanceBonus * 100;
            };

            const calculateNecklaceSpeed = (level) => {
                if (level === -1) {
                    return 0;
                }
                const baseSpeed = getNecklaceBaseSpeed();
                // 项链的强化加成计算方式不同，是乘以5
                const enhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[level] || 0) * 5 / 100;
                return baseSpeed * enhanceBonus * 100;
            };

            const calculateGloveBonus = (level) => {
                if (level === -1) {
                    return 0;
                }
                const baseBonus = getGloveBaseBonus();
                const enhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[level] || 0) / 100;
                return baseBonus * enhanceBonus * 100;
            };

            const calculateChanceCapeSpeed = (level, type) => {
                if (type === 'none') {
                    return 0;
                }
                const baseSpeed = getChanceCapeBaseSpeed(type);
                // 披风的强化效果是其他普通装备的5倍
                const capeEnhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[level] || 0) * 5 / 100;
                return baseSpeed * capeEnhanceBonus * 100;
            };

            const calculateDrinkConcentrationBonus = (level) => {
                if (level === -1) {
                    return 0;
                }
                const baseBonus = getDrinkConcentrationBase();
                const enhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[level] || 0) / 100;
                return baseBonus * enhanceBonus * 100;
            };

            const enhancerBonus = calculateEnhancerBonus(config.virtual.enhancer_type, config.virtual.enhancer_level);
            const enhancersTopSpeed = calculateEnhancerTopSpeed(config.virtual.enhancers_top_level);
            const enhancersBottomSpeed = calculateEnhancerBottomSpeed(config.virtual.enhancers_bottom_level);
            const necklaceSpeed = calculateNecklaceSpeed(config.virtual.necklace_level);
            const gloveBonus = calculateGloveBonus(config.virtual.glove_level);
            const chanceCapeSpeed = calculateChanceCapeSpeed(config.virtual.chance_cape_level, config.virtual.chance_cape_type);
            const drinkConcentrationBonus = calculateDrinkConcentrationBonus(config.virtual.drink_pouch_level);

            return cacheResult({
                ...ENHANCE_DEFAULT_PARAMS,
                enhancing_level: config.virtual.enhancing_level,
                laboratory_level: config.virtual.laboratory_level,
                enhancer_bonus: enhancerBonus,
                enhancers_top_speed: enhancersTopSpeed,
                enhancers_bottom_speed: enhancersBottomSpeed,
                necklace_speed: necklaceSpeed,
                glove_bonus: gloveBonus,
                chance_cape_speed: chanceCapeSpeed,
                drink_concentration_bonus: drinkConcentrationBonus,
                community_enhancing_speed_level: communityEnhancingSpeedLevel,
                community_enhancing_speed_bonus: communityEnhancingSpeedBonus,
                tea_enhancing: config.virtual.tea_type === 'basic',
                tea_super_enhancing: config.virtual.tea_type === 'super',
                tea_ultra_enhancing: config.virtual.tea_type === 'ultra',
                champion_achievement: config.virtual.champion_achievement
            });
        }

        const teaParams = mooncakeGetEnhancingTeaParams();
        const res = {
            ...ENHANCE_NEUTRAL_PARAMS,
            ...teaParams,
            champion_achievement: mooncakeHasChampionAchievement(),
            drink_concentration_bonus: getDrinkConcentrationBonus(),
            community_enhancing_speed_level: communityEnhancingSpeedLevel,
            community_enhancing_speed_bonus: communityEnhancingSpeedBonus,
            enhancers_top_speed: 0,
            enhancers_bottom_speed: 0,
            necklace_speed: 0,
            chance_cape_speed: 0
        };

        for (const skill of mooncakeCollectionValues(characterSkills)) {
            const skillHrid = skill?.skillHrid || skill?.hrid || '';
            if (skillHrid === '/skills/enhancing') {
                    res.enhancing_level = Number(skill.level) || 0;
                    break;
            }
        }

        let foundObservatory = false;
        if (characterHouseRoomMap) {
            for (const [key, room] of mooncakeCollectionEntries(characterHouseRoomMap)) {
                if (!room) continue;
                const hrid = room.houseRoomHrid || key || "";
                if (hrid.includes("observatory")) {
                    const observatoryLevel = room.level;
                    if (observatoryLevel !== undefined && observatoryLevel !== null) {
                        res.laboratory_level = Number(observatoryLevel) || 0;
                        foundObservatory = true;
                        break;
                    }
                }
            }
            if (!foundObservatory) {
                for (const [key, room] of mooncakeCollectionEntries(characterHouseRoomMap)) {
                    if (!room) continue;
                    const hrid = room.houseRoomHrid || key || "";
                    if (hrid.includes("laboratory")) {
                        const laboratoryLevel = room.level;
                        if (laboratoryLevel !== undefined && laboratoryLevel !== null) {
                            res.laboratory_level = Number(laboratoryLevel) || 0;
                            break;
                        }
                    }
                }
            }
        }

        let foundEnhancer = false;
        if (characterItems) {
            for (const it of mooncakeRelevantCharacterItems(characterItems)) {
                if (!it.itemLocationHrid || it.itemLocationHrid === "/item_locations/inventory") continue;
                const hrid = it.itemHrid;
                const detail = itemDetailMap?.[hrid];
                if (!detail) continue;
                const noncombat = detail?.equipmentDetail?.noncombatStats;
                if (noncombat && noncombat.enhancingSuccess && !foundEnhancer) {
                    const instanceLevel = Math.min(Math.max(Number(it.enhancementLevel ?? 0), 0), 20);
                    const baseFraction = noncombat.enhancingSuccess || 0.0;
                    if (instanceLevel >= 1) {
                        const multiplier = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[instanceLevel] || 0) / 100.0;
                        const finalFraction = baseFraction * multiplier;
                        res.enhancer_bonus = Number((finalFraction * 100).toFixed(4));
                    } else {
                        res.enhancer_bonus = Number((baseFraction * 100).toFixed(4));
                    }
                    foundEnhancer = true;
                }
                if (hrid === '/items/enchanted_gloves') {
                    const enhancingSpeed = detail?.equipmentDetail?.noncombatStats?.enhancingSpeed;
                    if (enhancingSpeed) {
                        const enhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[it.enhancementLevel || 0] || 0) / 100;
                        res.glove_bonus = enhancingSpeed * enhanceBonus * 100;
                    }
                }
                if (hrid === "/items/enhancers_top") {
                    const enhancingSpeed = detail?.equipmentDetail?.noncombatStats?.enhancingSpeed;
                    if (enhancingSpeed) {
                        const enhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[it.enhancementLevel || 0] || 0) / 100;
                        res.enhancers_top_speed = enhancingSpeed * enhanceBonus * 100;
                    }
                }
                if (hrid === "/items/enhancers_bottoms") {
                    const enhancingSpeed = detail?.equipmentDetail?.noncombatStats?.enhancingSpeed;
                    if (enhancingSpeed) {
                        const enhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[it.enhancementLevel || 0] || 0) / 100;
                        res.enhancers_bottom_speed = enhancingSpeed * enhanceBonus * 100;
                    }
                }
                if (hrid === "/items/necklace_of_speed" || hrid === "/items/philosophers_necklace") {
                    const skillingSpeed = detail?.equipmentDetail?.noncombatStats?.skillingSpeed;
                    if (skillingSpeed) {
                        const enhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[it.enhancementLevel || 0] || 0) * 5 / 100;
                        res.necklace_speed = skillingSpeed * enhanceBonus * 100;
                    }
                }
                // 处理机缘披风
                if (hrid === "/items/chance_cape" || hrid === "/items/chance_cape_refined") {
                    const enhancingSpeed = detail?.equipmentDetail?.noncombatStats?.enhancingSpeed;
                    if (enhancingSpeed) {
                        // 披风的强化效果是其他普通装备的5倍
                        const capeEnhanceBonus = 1 + (ITEM_ENHANCE_LEVEL_TO_BUFF_BONUS_MAP[it.enhancementLevel || 0] || 0) * 5 / 100;
                        res.chance_cape_speed = enhancingSpeed * capeEnhanceBonus * 100;
                    }
                }
            }
        }

        return cacheResult(res);
        } catch (err) {
            console.error('[Better Loot Tracker] 获取玩家强化参数时出错:', err);
            return {
                ...ENHANCE_NEUTRAL_PARAMS,
                drink_concentration_bonus: 0,
                enhancers_top_speed: 0,
                enhancers_bottom_speed: 0,
                necklace_speed: 0,
                chance_cape_speed: 0
            };
        }
    }

const ENHANCELATE_CACHE_LIMIT = 512;

const enhancelateCache = new Map();

const MOONCAKE_EXACT_ENHANCELATE_CACHE_LIMIT = 512;

const mooncakeExactEnhancelateCache = new Map();

function mooncakeSetBoundedMapEntry(cache, key, value, limit) {
        if (cache.has(key)) cache.delete(key);
        while (cache.size >= limit) {
            const oldestKey = cache.keys().next().value;
            if (oldestKey === undefined) break;
            cache.delete(oldestKey);
        }
        cache.set(key, value);
        return value;
    }

function cacheEnhancelateResult(key, value) {
        mooncakeSetBoundedMapEntry(enhancelateCache, key, value, ENHANCELATE_CACHE_LIMIT);
    }

function cacheMooncakeExactEnhancelateResult(key, value) {
        mooncakeSetBoundedMapEntry(
            mooncakeExactEnhancelateCache,
            key,
            value,
            MOONCAKE_EXACT_ENHANCELATE_CACHE_LIMIT
        );
    }

function buildEnhancelateCacheKey(itemHrid, stopAt, protectAt, itemLevel, totalSkillLevel, playerParams) {
        const chanceProfile = {
            enhancing_level: playerParams.enhancing_level,
            laboratory_level: playerParams.laboratory_level,
            enhancer_bonus: playerParams.enhancer_bonus,
            drink_concentration_bonus: playerParams.drink_concentration_bonus,
            tea_enhancing: !!playerParams.tea_enhancing,
            tea_super_enhancing: !!playerParams.tea_super_enhancing,
            tea_ultra_enhancing: !!playerParams.tea_ultra_enhancing,
            tea_blessed: !!playerParams.tea_blessed,
            champion_achievement: !!playerParams.champion_achievement
        };
        return JSON.stringify([stopAt, protectAt, itemLevel, totalSkillLevel, chanceProfile]);
    }

function Enhancelate(itemHrid, stopAt, protectAt, overrideParams = null, startLevel = 0) {
        const itemLevel = getBaseItemLevel(itemHrid);
        const playerParams = { ...getPlayerEnhanceParams(), ...(overrideParams || {}) };

        // 获取实际的强化等级和天文台等级
        const actualEnhancingLevel = playerParams.enhancing_level;
        const actualObservatoryLevel = playerParams.laboratory_level;

        // 获取暴饮之囊加成
        const drinkConcentrationBonus = playerParams.drink_concentration_bonus;
        const drinkConcentrationMultiplier = drinkConcentrationBonus ? (1 + drinkConcentrationBonus / 100) : 1;

        // 获取茶效果
        const teaEffects = {
            enhancing: playerParams.tea_enhancing,
            superEnhancing: playerParams.tea_super_enhancing,
            ultraEnhancing: playerParams.tea_ultra_enhancing,
            blessed: playerParams.tea_blessed
        };

        // 计算有效强化等级（包含茶的加成和暴饮之囊加成影响）
        const effectiveLevel = actualEnhancingLevel +
            (teaEffects.enhancing ? 3 * drinkConcentrationMultiplier : 0) +
            (teaEffects.superEnhancing ? 6 * drinkConcentrationMultiplier : 0) +
            (teaEffects.ultraEnhancing ? 8 * drinkConcentrationMultiplier : 0);

        // 获取强化器加成
        const enhancerBonus = playerParams.enhancer_bonus;

        const totalSkillLevel = getEnhancelateTotalSkillLevel();

        // 技能等级总和加成
        let skillTotalBonus = 0;
        if (playerParams.champion_achievement) {
            skillTotalBonus = 0.2; // 强化成功率 +0.2%
        }

        const normalizedStartLevel = Math.max(0, Math.min(
            Math.max(0, stopAt - 1),
            Math.floor(Number(startLevel) || 0)
        ));
        const baseCacheKey = buildEnhancelateCacheKey(itemHrid, stopAt, protectAt, itemLevel, totalSkillLevel, playerParams);
        const cacheKey = normalizedStartLevel === 0
            ? baseCacheKey
            : `${baseCacheKey}:start=${normalizedStartLevel}`;
        if (enhancelateCache.has(cacheKey)) {
            return enhancelateCache.get(cacheKey);
        }

        // 计算总加成
        let totalBonus;
        if (effectiveLevel >= itemLevel) {
            totalBonus = 1 + (0.05 * (effectiveLevel + actualObservatoryLevel - itemLevel) + enhancerBonus + skillTotalBonus) / 100;
        } else {
            totalBonus = 1 - 0.5 * (1 - effectiveLevel / itemLevel) + (0.05 * actualObservatoryLevel + enhancerBonus + skillTotalBonus) / 100;
        }

        // 建立马尔可夫矩阵
        let markov = math.zeros(21, 21);
        for (let i = 0; i < stopAt; i++) {
            const successChance = (SUCCESS_RATE[i] / 100.0) * totalBonus;
            const destination = i >= protectAt ? i - 1 : 0;

            if (teaEffects.blessed) {
                // 祝福茶效果也受暴饮之囊加成影响
                const blessedEffect = 0.01 * drinkConcentrationMultiplier;
                markov.set([i, Math.min(i + 2, 20)], successChance * blessedEffect);
                markov.set([i, i + 1], successChance * (1 - blessedEffect));
                markov.set([i, destination], 1 - successChance);
            } else {
                markov.set([i, i + 1], successChance);
                markov.set([i, destination], 1.0 - successChance);
            }
        }
        markov.set([stopAt, stopAt], 1.0);

        // 计算期望强化次数
        let Q = markov.subset(math.index(math.range(0, stopAt), math.range(0, stopAt)));
        const M = math.inv(math.subtract(math.identity(stopAt), Q));
        const attemptsArray = M.subset(math.index(
            math.range(normalizedStartLevel, normalizedStartLevel + 1),
            math.range(0, stopAt)
        ));
        const attempts = typeof attemptsArray === "number"
            ? attemptsArray
            : math.flatten(math.row(attemptsArray, 0).valueOf()).reduce((a, b) => a + b, 0);

        // 计算期望保护次数
        let protects = 0;
        if (protectAt >= 1 && protectAt < stopAt) {
            const protectAttempts = M.subset(math.index(
                math.range(normalizedStartLevel, normalizedStartLevel + 1),
                math.range(protectAt, stopAt)
            ));
            const protectAttemptsArray = typeof protectAttempts === "number"
                ? [protectAttempts]
                : math.flatten(math.row(protectAttempts, 0).valueOf());
            protects = protectAttemptsArray.map((a, i) =>
                a * markov.get([i + protectAt, i + protectAt - 1])
            ).reduce((a, b) => a + b, 0);
        }

        // 计算期望经验值
        let totalExp = 0;
        for (let i = 0; i < stopAt; i++) {
            const successChance = (SUCCESS_RATE[i] / 100.0) * totalBonus;
            const baseExp = 1.4 * (1 + i) * (10 + itemLevel);
            const expPerAction = (successChance + 0.1 * (1 - successChance)) * baseExp;
            totalExp += expPerAction;
        }
        const expectedExp = attempts * (totalExp / stopAt);

        const result = {
            actions: attempts,
            protectCount: protects,
            exp: expectedExp
        };

        cacheEnhancelateResult(cacheKey, result);
        return result;
    }

function mooncakeEnhancelateExactLevel(itemHrid, stopAt, protectAt, overrideParams = null) {
        const target = Number(stopAt);
        if (!Number.isInteger(target) || target < 0 || target > 20) return null;
        if (target === 0) {
            return { actions: 0, protectCount: 0, exp: 0, baseItemCount: 1, overshootProbability: 0, exactTarget: true };
        }

        const playerParams = { ...getPlayerEnhanceParams(), ...(overrideParams || {}) };
        if (!playerParams.tea_blessed) {
            const standard = Enhancelate(itemHrid, target, protectAt, overrideParams);
            return standard ? { ...standard, baseItemCount: 1, overshootProbability: 0, exactTarget: true } : null;
        }

        const itemLevel = getBaseItemLevel(itemHrid);
        const totalSkillLevel = getEnhancelateTotalSkillLevel();
        const cacheKey = `exact:${buildEnhancelateCacheKey(itemHrid, target, protectAt, itemLevel, totalSkillLevel, playerParams)}`;
        if (mooncakeExactEnhancelateCache.has(cacheKey)) return mooncakeExactEnhancelateCache.get(cacheKey);

        try {
            const drinkMultiplier = playerParams.drink_concentration_bonus
                ? 1 + playerParams.drink_concentration_bonus / 100
                : 1;
            const effectiveLevel = playerParams.enhancing_level +
                (playerParams.tea_enhancing ? 3 * drinkMultiplier : 0) +
                (playerParams.tea_super_enhancing ? 6 * drinkMultiplier : 0) +
                (playerParams.tea_ultra_enhancing ? 8 * drinkMultiplier : 0);
            const skillBonus = playerParams.champion_achievement ? 0.2 : 0;
            const totalBonus = effectiveLevel >= itemLevel
                ? 1 + (0.05 * (effectiveLevel + playerParams.laboratory_level - itemLevel) + playerParams.enhancer_bonus + skillBonus) / 100
                : 1 - 0.5 * (1 - effectiveLevel / itemLevel) + (0.05 * playerParams.laboratory_level + playerParams.enhancer_bonus + skillBonus) / 100;
            const blessedEffect = 0.01 * drinkMultiplier;
            const markov = math.zeros(target, target);
            const overshootPerVisit = new Array(target).fill(0);
            const successChances = new Array(target).fill(0);

            for (let level = 0; level < target; level++) {
                const successChance = (SUCCESS_RATE[level] / 100) * totalBonus;
                successChances[level] = successChance;
                const failureDestination = level >= protectAt ? level - 1 : 0;
                const jumpProbability = successChance * blessedEffect;
                const jumpDestination = Math.min(level + 2, 20);
                if (jumpDestination < target) {
                    markov.set([level, jumpDestination], markov.get([level, jumpDestination]) + jumpProbability);
                } else if (jumpDestination > target) {
                    overshootPerVisit[level] += jumpProbability;
                }
                const normalProbability = successChance * (1 - blessedEffect);
                if (level + 1 < target) {
                    markov.set([level, level + 1], markov.get([level, level + 1]) + normalProbability);
                }
                markov.set([level, failureDestination], markov.get([level, failureDestination]) + 1 - successChance);
            }

            const Q = markov.subset(math.index(math.range(0, target), math.range(0, target)));
            const M = math.inv(math.subtract(math.identity(target), Q));
            const firstRow = typeof M === 'number'
                ? [M]
                : math.flatten(math.row(M, 0).valueOf());
            const cycleActions = firstRow.reduce((sum, value) => sum + value, 0);
            let cycleProtects = 0;
            if (protectAt >= 1 && protectAt < target) {
                for (let level = protectAt; level < target; level++) {
                    cycleProtects += firstRow[level] * (markov.get([level, level - 1]) || 0);
                }
            }
            const overshootProbability = Math.max(0, Math.min(1 - 1e-12,
                firstRow.reduce((sum, visits, level) => sum + visits * overshootPerVisit[level], 0)));
            const exactProbability = 1 - overshootProbability;
            let cycleExpPerAction = 0;
            for (let level = 0; level < target; level++) {
                const baseExp = 1.4 * (1 + level) * (10 + itemLevel);
                cycleExpPerAction += (successChances[level] + 0.1 * (1 - successChances[level])) * baseExp;
            }
            const cycleExp = cycleActions * (cycleExpPerAction / target);
            const result = {
                actions: cycleActions / exactProbability,
                protectCount: cycleProtects / exactProbability,
                exp: cycleExp / exactProbability,
                baseItemCount: 1 / exactProbability,
                overshootProbability,
                exactTarget: true
            };
            cacheMooncakeExactEnhancelateResult(cacheKey, result);
            return result;
        } catch (_) {
            const fallback = Enhancelate(itemHrid, target, protectAt, overrideParams);
            return fallback ? { ...fallback, baseItemCount: 1, overshootProbability: 0, exactTarget: false } : null;
        }
    }

const MOONCAKE_ROUTE_SELECTION_EPSILON = 1e-8;

function mooncakeGetRouteEquivalentCost(route, standardHourlyWage = null) {
        const totalCost = Number(route?.totalCost);
        const totalTimeHours = Number(route?.totalTimeHours);
        const configuredHourlyWage = Number.isFinite(Number(standardHourlyWage))
            ? Number(standardHourlyWage)
            : mooncakeGetEnhancementStandardHourlyWage();
        if (!Number.isFinite(totalCost) || !Number.isFinite(totalTimeHours) || totalTimeHours < 0) return null;
        return totalCost + Math.max(0, configuredHourlyWage) * totalTimeHours;
    }

function mooncakeCompareStandardHourlyRoutes(left, right, standardHourlyWage) {
        const leftEquivalentCost = mooncakeGetRouteEquivalentCost(left, standardHourlyWage);
        const rightEquivalentCost = mooncakeGetRouteEquivalentCost(right, standardHourlyWage);
        if (leftEquivalentCost < rightEquivalentCost - MOONCAKE_ROUTE_SELECTION_EPSILON) return -1;
        if (leftEquivalentCost > rightEquivalentCost + MOONCAKE_ROUTE_SELECTION_EPSILON) return 1;

        // When time-adjusted costs are equal, prefer the route that starts
        // protection earlier. That keeps a numerical tie from adding risk.
        const leftProtectAt = Number(left?.protectAt);
        const rightProtectAt = Number(right?.protectAt);
        if (Number.isInteger(leftProtectAt) && Number.isInteger(rightProtectAt) && leftProtectAt !== rightProtectAt) {
            return leftProtectAt - rightProtectAt;
        }

        const leftCost = Number(left?.totalCost);
        const rightCost = Number(right?.totalCost);
        if (leftCost < rightCost - MOONCAKE_ROUTE_SELECTION_EPSILON) return -1;
        if (leftCost > rightCost + MOONCAKE_ROUTE_SELECTION_EPSILON) return 1;
        const leftTime = Number(left?.totalTimeHours);
        const rightTime = Number(right?.totalTimeHours);
        if (leftTime < rightTime - MOONCAKE_ROUTE_SELECTION_EPSILON) return -1;
        if (leftTime > rightTime + MOONCAKE_ROUTE_SELECTION_EPSILON) return 1;
        return 0;
    }

function mooncakePickLowestCostTraditionalRoute(candidates) {
        return candidates.reduce((best, candidate) => {
            const candidateCost = Number(candidate.totalCost);
            const bestCost = Number(best?.totalCost);
            if (!best || candidateCost < bestCost - MOONCAKE_ROUTE_SELECTION_EPSILON) return candidate;
            if (Math.abs(candidateCost - bestCost) > MOONCAKE_ROUTE_SELECTION_EPSILON) return best;
            const candidateTime = Number(candidate.totalTimeHours);
            const bestTime = Number(best.totalTimeHours);
            return Number.isFinite(candidateTime) &&
                (!Number.isFinite(bestTime) || candidateTime < bestTime - MOONCAKE_ROUTE_SELECTION_EPSILON)
                ? candidate
                : best;
        }, null);
    }

function mooncakePickHighestHourlyTraditionalRoute(candidates) {
        return candidates.reduce((best, candidate) => {
            const candidateHourly = Number(candidate.hourlyWage);
            const bestHourly = Number(best?.hourlyWage);
            if (!best || candidateHourly > bestHourly + MOONCAKE_ROUTE_SELECTION_EPSILON) return candidate;
            if (Math.abs(candidateHourly - bestHourly) > MOONCAKE_ROUTE_SELECTION_EPSILON) return best;
            const candidateCost = Number(candidate.totalCost);
            const bestCost = Number(best.totalCost);
            if (candidateCost < bestCost - MOONCAKE_ROUTE_SELECTION_EPSILON) return candidate;
            if (Math.abs(candidateCost - bestCost) > MOONCAKE_ROUTE_SELECTION_EPSILON) return best;
            const candidateTime = Number(candidate.totalTimeHours);
            const bestTime = Number(best.totalTimeHours);
            return Number.isFinite(candidateTime) &&
                (!Number.isFinite(bestTime) || candidateTime < bestTime - MOONCAKE_ROUTE_SELECTION_EPSILON)
                ? candidate
                : best;
        }, null);
    }

function mooncakeSelectStandardHourlyRoute(candidates, options = {}) {
        const standardHourlyWage = Number.isFinite(Number(options.standardHourlyWage))
            ? Math.max(0, Number(options.standardHourlyWage))
            : mooncakeGetEnhancementStandardHourlyWage();
        const ranked = (candidates || [])
            .filter(route => Number.isFinite(Number(route?.totalCost)) &&
                Number.isFinite(Number(route?.totalTimeHours)) && Number(route.totalTimeHours) >= 0)
            .map(route => ({
                route,
                equivalentCost: mooncakeGetRouteEquivalentCost(route, standardHourlyWage)
            }))
            .filter(entry => Number.isFinite(entry.equivalentCost))
            .sort((left, right) => mooncakeCompareStandardHourlyRoutes(
                left.route,
                right.route,
                standardHourlyWage
            ));
        if (!ranked.length) return null;

        const selected = ranked[0];
        const alternate = ranked.find(entry => entry.route !== selected.route) || null;
        return {
            ...selected.route,
            routeSelectionPolicy: {
                type: 'standard-hourly-equivalent-cost',
                requestedObjective: 'standard',
                standardHourlyWage,
                standardHourlyM: standardHourlyWage / 1e6,
                selectedEquivalentCost: selected.equivalentCost,
                alternateEquivalentCost: alternate?.equivalentCost ?? null,
                selectedRoute: selected.route,
                alternateRoute: alternate?.route || null
            }
        };
    }

function mooncakeSelectTraditionalRouteByObjective(candidates, objective, hasHourlySignal = true, options = {}) {
        const valid = (candidates || []).filter(candidate =>
            Number.isInteger(Number(candidate?.protectAt)) &&
            Number.isFinite(Number(candidate?.totalCost))
        );
        if (!valid.length) return null;

        const selectionMode = mooncakeGetEnhancementRouteSelectionMode(objective);
        if (selectionMode === 'standard') {
            return mooncakeSelectStandardHourlyRoute(valid, options);
        }
        const highestProfit = mooncakePickLowestCostTraditionalRoute(valid);
        if (selectionMode === 'minCost' || !hasHourlySignal) return highestProfit;

        const hourlyCandidates = valid.filter(candidate => Number.isFinite(Number(candidate.hourlyWage)));
        const highestHourly = hourlyCandidates.length
            ? mooncakePickHighestHourlyTraditionalRoute(hourlyCandidates)
            : null;
        if (!highestHourly) return highestProfit;
        return highestHourly;
    }

function findBestProtectLevel(itemHrid, targetLevel, marketData, targetPrice, options = {}) {
        const enhancementCosts = getEnhancementCosts(itemHrid);
        if (!Array.isArray(enhancementCosts)) return null;

        // 计算每次强化的材料成本
        let perActionCost = 0;
        for (const cost of enhancementCosts) {
            const count = Number(cost?.count);
            const price = mooncakeResolveGenericMaterialPrice(cost?.itemHrid, marketData);
            // A missing quote is not a free material. Keep legacy +1..+12
            // routes consistent with the generic route builder and reject the
            // estimate until every required input has a usable price.
            if (!cost?.itemHrid || !(count >= 0) || !(price > 0)) return null;
            perActionCost += price * cost.count;
        }

        // 计算保护成本
        const protectionItems = getProtectionItems(itemHrid);
        let minProtectCost = Infinity;
        for (const protectHrid of protectionItems) {
            const price = hostProtectionPrice(itemHrid, protectHrid, marketData);
            if (price > 0 && price < minProtectCost) {
                minProtectCost = price;
            }
        }
        if (minProtectCost === Infinity) minProtectCost = 0;

        const marketRoot = marketData?.marketData?.[itemHrid];
        // Whiteboard replacement cost follows the configured material/product
        // acquisition chains, then keeps the cheaper complete route.
        const baseResolution = mooncakeResolveGenericBaseItemPrice(itemHrid, marketData);
        const baseItemPrice = Number(baseResolution?.price) || 0;
        const baseItemSource = baseResolution?.source || null;
        if (!(baseItemPrice > 0)) return null;

        // 获取目标等级的价格用于计算利润和工时费
        const targetPriceObject = marketRoot?.[targetLevel.toString()];
        const targetLeftPrice = targetPrice || targetPriceObject?.a || 0;
        const routeSelectionMode = mooncakeGetEnhancementRouteSelectionMode(options?.objective);

        // 遍历所有可能的保护等级找到最优
        const protectResults = [];
        const startProtect = targetLevel === 1 ? 1 : 2;

        for (let protectAt = startProtect; protectAt <= targetLevel; protectAt++) {
            const sim = Enhancelate(itemHrid, targetLevel, protectAt);
            if (sim.protectCount > 1e-9 && !(minProtectCost > 0)) continue;
            const totalCost = baseItemPrice + perActionCost * sim.actions + minProtectCost * sim.protectCount;
            const totalTimeHours = sim.actions > 0 ? calcEnhancingTimeSeconds(itemHrid, sim.actions) / 3600 : 0;

            // 计算工时费
            let hourlyWage = 0;
            if (targetLeftPrice > 0 && totalCost > 0 && totalTimeHours > 0) {
                // 计算利润和工时费
                const profit = targetLeftPrice * MOONCAKE_MARKET_SELL_NET_FACTOR - totalCost;
                hourlyWage = profit / totalTimeHours;
            }

            // 计算经验/小时
            let expPerHour = 0;
            if (sim.exp && totalTimeHours > 0) {
                expPerHour = sim.exp / totalTimeHours;
            }

            const result = {
                routeType: 'traditional',
                protectAt: protectAt,
                expectedActions: sim.actions,
                expectedProtects: sim.protectCount,
                perActionCost: perActionCost,
                minProtectCost: minProtectCost,
                baseItemPrice: baseItemPrice,
                baseItemSource: baseItemSource,
                totalCost: totalCost,
                totalTimeHours: totalTimeHours,
                hourlyWage: hourlyWage,
                exp: sim.exp || 0,
                expPerHour: expPerHour
            };
            protectResults.push(result);
        }

        return mooncakeSelectTraditionalRouteByObjective(
            protectResults,
            routeSelectionMode,
            Number(targetLeftPrice) > 0,
            {
                price: targetLeftPrice,
                standardHourlyWage: options?.standardHourlyWage,
                applyProtectionThreshold: options?.applyProtectionThreshold !== false
            }
        );
    }

const MOONCAKE_PHILOSOPHERS_MIRROR_HRID = '/items/philosophers_mirror';

const MOONCAKE_MIRROR_OUTPUT_MIN_LEVEL = 13;

const MOONCAKE_ENHANCEMENT_ROUTE_CACHE_LIMIT = 96;

const MOONCAKE_ENHANCEMENT_ROUTE_PAIR_CACHE_LIMIT = 192;

const mooncakeEnhancementRouteCandidateCache = new Map();

const mooncakeEnhancementRoutePairCache = new Map();

function mooncakeCacheEnhancementRouteCandidates(key, value) {
        return mooncakeSetBoundedMapEntry(
            mooncakeEnhancementRouteCandidateCache,
            key,
            value,
            MOONCAKE_ENHANCEMENT_ROUTE_CACHE_LIMIT
        );
    }

function mooncakeGetMirrorArtisanMultiplier() {
        return mooncakeGetArtisanMaterialMultiplier();
    }

function mooncakeGetArtisanCraftingCost(itemHrid, marketData, processedItems = new Set()) {
        if (!itemHrid || processedItems.has(itemHrid)) return 0;
        const recipe = getCraftingRecipe(itemHrid);
        if (!recipe?.inputs?.length) return 0;

        const nextProcessed = new Set(processedItems);
        nextProcessed.add(itemHrid);
        const artisanMultiplier = mooncakeGetMirrorArtisanMultiplier();
        const recipeMaterialMultiplier = mooncakeGetRecipeMaterialMultiplier(itemHrid, artisanMultiplier);
        let totalCost = 0;
        for (const input of recipe.inputs) {
            const count = Number(input?.count);
            if (!input?.itemHrid || !(count > 0)) return 0;
            let unitPrice = getMarketPrice(input.itemHrid, marketData);
            if (!(unitPrice > 0)) {
                unitPrice = mooncakeGetArtisanCraftingCost(input.itemHrid, marketData, nextProcessed);
            }
            if (!(unitPrice > 0)) return 0;
            const adjustedCount = input.isFixedUpgradeItem === true
                ? count
                : count * recipeMaterialMultiplier;
            totalCost += unitPrice * adjustedCount;
        }
        const outputCount = Math.max(1, Number(recipe.outputCount) || 1);
        return totalCost / outputCount;
    }

function mooncakeResolveGenericMirrorUnitCost(marketData) {
        const marketAsk = Number(marketData?.marketData?.[MOONCAKE_PHILOSOPHERS_MIRROR_HRID]?.['0']?.a);
        const craftCost = mooncakeGetArtisanCraftingCost(MOONCAKE_PHILOSOPHERS_MIRROR_HRID, marketData);
        const choices = [];
        if (Number.isFinite(marketAsk) && marketAsk > 0) choices.push({ unitCost: marketAsk, source: 'market' });
        if (Number.isFinite(craftCost) && craftCost > 0) choices.push({ unitCost: craftCost, source: 'craft' });
        if (!choices.length) return null;
        choices.sort((a, b) => a.unitCost - b.unitCost || a.source.localeCompare(b.source));
        return { ...choices[0], marketAsk: marketAsk > 0 ? marketAsk : 0, craftCost: craftCost > 0 ? craftCost : 0 };
    }

function mooncakeResolveGenericBaseItemPrice(itemHrid, marketData) {
        const policy = mooncakeGetBaseItemCostPricePolicy();
        const cache = mooncakeGetBaseItemCostResolutionCache(marketData);
        const cacheKey = cache ? mooncakeGetBaseItemCostResolutionCacheKey(itemHrid, policy) : '';
        const cached = cache?.get(cacheKey);
        if (cached) {
            cache.delete(cacheKey);
            cache.set(cacheKey, cached);
            return cached;
        }
        const craftingCost = mooncakeGetConfiguredBaseItemCraftingCost(itemHrid, marketData, policy);
        const productPrice = mooncakeGetBaseItemCostPolicyQuote(itemHrid, marketData, policy.product);

        // Only these two completed routes compete: material-route crafting and
        // a +0 finished-product quote. The ready-made quote is intentionally
        // single-choice, so a missing left quote cannot silently fall through
        // to a much lower buy order.
        const resolution = craftingCost > 0 && productPrice > 0
            ? (craftingCost < productPrice
                ? { price: craftingCost, source: 'craft', craftingCost, productPrice }
                : { price: productPrice, source: 'market', craftingCost, productPrice })
            : (craftingCost > 0
                ? { price: craftingCost, source: 'craft', craftingCost, productPrice }
                : (productPrice > 0
                    ? { price: productPrice, source: 'market', craftingCost, productPrice }
                    : { price: 0, source: null, craftingCost, productPrice }));
        if (cache) {
            cache.set(cacheKey, resolution);
            while (cache.size > MOONCAKE_BASE_ITEM_COST_RESOLUTION_CACHE_LIMIT) {
                cache.delete(cache.keys().next().value);
            }
        }
        return resolution;
    }

function mooncakeBuildEnhancementCostContext(itemHrid, marketData, options = {}) {
        const enhancementCosts = getEnhancementCosts(itemHrid);
        if (!Array.isArray(enhancementCosts)) return null;
        const resolveMaterialPrice = options.resolveMaterialPrice;
        const resolveProtectionPrice = options.resolveProtectionPrice || resolveMaterialPrice;
        const resolveBaseItemPrice = options.resolveBaseItemPrice;
        if (typeof resolveMaterialPrice !== 'function' || typeof resolveBaseItemPrice !== 'function') return null;

        let perActionCost = 0;
        for (const cost of enhancementCosts) {
            const count = Number(cost?.count);
            const unitPrice = Number(resolveMaterialPrice(cost?.itemHrid, marketData));
            if (!cost?.itemHrid || !(count >= 0) || !(unitPrice > 0)) return null;
            perActionCost += unitPrice * count;
        }

        let minProtectCost = Infinity;
        let protectionItemHrid = null;
        for (const protectHrid of [...new Set(getProtectionItems(itemHrid) || [])]) {
            const unitPrice = Number(resolveProtectionPrice(protectHrid, marketData));
            if (unitPrice > 0 && unitPrice < minProtectCost) {
                minProtectCost = unitPrice;
                protectionItemHrid = protectHrid;
            }
        }
        if (!Number.isFinite(minProtectCost)) minProtectCost = 0;

        const baseResolution = resolveBaseItemPrice(itemHrid, marketData);
        const baseItemPrice = Number(baseResolution?.price ?? baseResolution);
        if (!(baseItemPrice > 0)) return null;
        return {
            itemHrid,
            perActionCost,
            minProtectCost,
            protectionItemHrid,
            baseItemPrice,
            baseItemSource: typeof baseResolution === 'object' ? baseResolution?.source || null : null,
            secondsPerAction: calcEnhancingSecondsPerAction(itemHrid),
            traditionalPlans: new Map()
        };
    }

function mooncakeResolveGenericMaterialPrice(materialHrid, marketData) {
        let price = getMarketPrice(materialHrid, marketData);
        if (!(price > 0)) price = getCraftingCost(materialHrid, marketData);
        return price;
    }

function mooncakeBuildGenericEnhancementCostContext(itemHrid, marketData) {
        return mooncakeBuildEnhancementCostContext(itemHrid, marketData, {
            resolveMaterialPrice: mooncakeResolveGenericMaterialPrice,
            resolveProtectionPrice: (protectHrid, sourceMarketData) => hostProtectionPrice(itemHrid, protectHrid, sourceMarketData),
            resolveBaseItemPrice: mooncakeResolveGenericBaseItemPrice
        });
    }

function mooncakeBuildTraditionalUnitPlans(context, targetLevel, options = {}) {
        const level = Number(targetLevel);
        if (!Number.isInteger(level) || level < 0 || level > 20) return [];
        const exactLevel = !!options.exactLevel;
        const cacheKey = `${exactLevel ? 'exact' : 'standard'}:${level}`;
        if (context.traditionalPlans.has(cacheKey)) return context.traditionalPlans.get(cacheKey);

        const plans = [];
        if (level === 0) {
            plans.push({
                routeType: 'traditional',
                protectAt: null,
                protectionItemHrid: null,
                expectedActions: 0,
                expectedProtects: 0,
                traditionalActions: 0,
                traditionalProtects: 0,
                perActionCost: context.perActionCost,
                minProtectCost: context.minProtectCost,
                baseItemPrice: context.baseItemPrice,
                baseItemSource: context.baseItemSource || null,
                baseItemCost: context.baseItemPrice,
                materialCost: 0,
                protectCost: 0,
                mirrorCount: 0,
                mirrorCost: 0,
                totalCost: context.baseItemPrice,
                totalTimeHours: 0,
                exp: 0,
                expPerHour: 0
            });
        } else {
            const firstProtectAt = level === 1 ? 1 : 2;
            for (let protectAt = firstProtectAt; protectAt <= level; protectAt++) {
                let simulation;
                try {
                    simulation = exactLevel
                        ? mooncakeEnhancelateExactLevel(context.itemHrid, level, protectAt)
                        : Enhancelate(context.itemHrid, level, protectAt);
                } catch (_) {
                    continue;
                }
                const actions = Number(simulation?.actions);
                const protects = Math.max(0, Number(simulation?.protectCount) || 0);
                if (!(actions > 0)) continue;
                if (protects > 1e-9 && !(context.minProtectCost > 0)) continue;
                const baseItemCount = Math.max(1, Number(simulation?.baseItemCount) || 1);
                const materialCost = context.perActionCost * actions;
                const protectCost = context.minProtectCost * protects;
                const totalTimeHours = context.secondsPerAction * actions / 3600;
                plans.push({
                    routeType: 'traditional',
                    protectAt,
                    protectionItemHrid: protects > 1e-9 ? context.protectionItemHrid : null,
                    expectedActions: actions,
                    expectedProtects: protects,
                    traditionalActions: actions,
                    traditionalProtects: protects,
                    perActionCost: context.perActionCost,
                    minProtectCost: context.minProtectCost,
                    baseItemPrice: context.baseItemPrice,
                    baseItemSource: context.baseItemSource || null,
                    baseItemCost: context.baseItemPrice * baseItemCount,
                    materialCost,
                    protectCost,
                    mirrorCount: 0,
                    mirrorCost: 0,
                    totalCost: context.baseItemPrice * baseItemCount + materialCost + protectCost,
                    totalTimeHours,
                    exp: Number(simulation?.exp) || 0,
                    expPerHour: totalTimeHours > 0 ? (Number(simulation?.exp) || 0) / totalTimeHours : 0
                });
            }
        }
        context.traditionalPlans.set(cacheKey, plans);
        return plans;
    }

function mooncakeCalculateRefinementCarryoverCost(relation, marketData, resolveMaterialPrice) {
        if (!relation?.actionDetail?.retainAllEnhancement || typeof resolveMaterialPrice !== 'function') return null;
        const outputCount = Math.max(1, Number(relation.outputCount) || 1);
        // 当前已确认精炼一次只产出一件装备。若未来配方批量产出，不猜测强化等级如何分配。
        if (outputCount !== 1) return null;
        const artisanMultiplier = mooncakeGetMirrorArtisanMultiplier();
        let totalCost = 0;
        for (const input of relation.actionDetail.inputItems || []) {
            const count = Number(input?.count);
            if (!input?.itemHrid || !(count > 0)) return null;
            const unitPrice = Number(resolveMaterialPrice(input.itemHrid, marketData));
            if (!(unitPrice > 0)) return null;
            totalCost += unitPrice * count * artisanMultiplier;
        }
        return totalCost > 0 ? totalCost : null;
    }

function mooncakeBuildRefinementCarryoverPlans(normalPlans, refinementCost, refinementLevel) {
        if (!(refinementCost > 0)) return [];
        return normalPlans.map(plan => ({
            ...plan,
            routeType: 'refinementCarryover',
            refinementAtLevel: refinementLevel,
            refinementCost,
            materialCost: plan.materialCost + refinementCost,
            totalCost: plan.totalCost + refinementCost
        }));
    }

function mooncakeBuildFixedMirrorFlow(targetLevel, isRefined, mirrorOutputMin) {
        const target = Number(targetLevel);
        const minOutput = Number(mirrorOutputMin);
        if (!Number.isInteger(target) || !Number.isInteger(minOutput) ||
            target < minOutput || minOutput < MOONCAKE_MIRROR_OUTPUT_MIN_LEVEL || target > 20) {
            return null;
        }
        const normalNeeds = Array(21).fill(0);
        const refinedNeeds = Array(21).fill(0);
        const normalMirrorByOutput = Array(21).fill(0);
        const refinedMirrorByOutput = Array(21).fill(0);
        (isRefined ? refinedNeeds : normalNeeds)[target] = 1;

        for (let output = target; output >= minOutput; output--) {
            const normalCount = normalNeeds[output];
            if (normalCount > 1e-12) {
                normalNeeds[output] = 0;
                normalNeeds[output - 1] += normalCount;
                normalNeeds[output - 2] += normalCount;
                normalMirrorByOutput[output] += normalCount;
            }
            const refinedCount = refinedNeeds[output];
            if (refinedCount > 1e-12) {
                refinedNeeds[output] = 0;
                refinedNeeds[output - 1] += refinedCount;
                normalNeeds[output - 2] += refinedCount;
                refinedMirrorByOutput[output] += refinedCount;
            }
        }

        const mirrorCount = normalMirrorByOutput.reduce((sum, count) => sum + count, 0) +
            refinedMirrorByOutput.reduce((sum, count) => sum + count, 0);
        return {
            mirrorOutputMin: minOutput,
            normalNeeds,
            refinedNeeds,
            normalMirrorByOutput,
            refinedMirrorByOutput,
            mirrorCount
        };
    }

function mooncakeBuildMirrorRouteTemplate(itemHrid, targetLevel, marketData, options, mirrorOutputMin, getContext) {
        const isRefined = String(itemHrid || '').endsWith('_refined');
        let baseHrid = itemHrid;
        let refinementRelation = null;
        if (isRefined) {
            refinementRelation = mooncakeGetRefinementActionForItem(itemHrid);
            if (!refinementRelation || refinementRelation.refinedHrid !== itemHrid || !refinementRelation.baseHrid) return null;
            baseHrid = refinementRelation.baseHrid;
        }
        const flow = mooncakeBuildFixedMirrorFlow(targetLevel, isRefined, mirrorOutputMin);
        if (!flow) return null;
        const mirror = options.resolveMirrorUnitCost(marketData);
        if (!(mirror?.unitCost > 0)) return null;

        const normalContext = getContext(baseHrid);
        if (!normalContext) return null;
        const components = [];
        const addComponents = (sourceHrid, needs, kind, getPlans) => {
            // 镜路线可以从 +12 之后任意等级开始；开始点以下仍必须按传统强化制造。
            for (let level = 0; level < flow.mirrorOutputMin; level++) {
                const quantity = Number(needs[level]) || 0;
                if (!(quantity > 1e-12)) continue;
                const plans = getPlans(level);
                if (!plans.length) return false;
                components.push({ itemHrid: sourceHrid, level, quantity, kind, plans });
            }
            return true;
        };

        if (!addComponents(baseHrid, flow.normalNeeds, 'normal', level => mooncakeBuildTraditionalUnitPlans(normalContext, level, { exactLevel: true }))) return null;
        if (isRefined) {
            const refinedContext = getContext(itemHrid);
            const carryoverCost = mooncakeCalculateRefinementCarryoverCost(
                refinementRelation,
                marketData,
                options.resolveRefinementMaterialPrice
            );
            const getRefinedPlans = level => {
                const directPlans = refinedContext ? mooncakeBuildTraditionalUnitPlans(refinedContext, level, { exactLevel: true }) : [];
                const carryoverPlans = carryoverCost > 0
                    ? mooncakeBuildRefinementCarryoverPlans(
                        mooncakeBuildTraditionalUnitPlans(normalContext, level, { exactLevel: true }),
                        carryoverCost,
                        level
                    )
                    : [];
                return [...directPlans, ...carryoverPlans];
            };
            if (!addComponents(itemHrid, flow.refinedNeeds, 'refined', getRefinedPlans)) return null;
        }
        if (!components.length || !(flow.mirrorCount > 0)) return null;
        return {
            routeType: 'philosophersMirror',
            mirrorStartLevel: flow.mirrorOutputMin - 1,
            mirrorOutputMin: flow.mirrorOutputMin,
            mirrorCount: flow.mirrorCount,
            mirrorUnitCost: mirror.unitCost,
            mirrorSource: mirror.source,
            mirrorMarketAsk: mirror.marketAsk || 0,
            mirrorCraftCost: mirror.craftCost || 0,
            normalNeeds: flow.normalNeeds,
            refinedNeeds: flow.refinedNeeds,
            components
        };
    }

function mooncakePickMirrorComponentPlans(template, lambda = 0) {
        return template.components.map(component => {
            let best = null;
            for (const plan of component.plans) {
                const score = plan.totalCost + lambda * plan.totalTimeHours;
                if (!best || score < best.score - 1e-8 ||
                    (Math.abs(score - best.score) <= 1e-8 && plan.totalCost < best.plan.totalCost)) {
                    best = { plan, score };
                }
            }
            return { ...component, plan: best?.plan || null };
        }).filter(component => component.plan);
    }

function mooncakeAggregateMirrorRoute(template, selectedComponents) {
        const route = {
            routeType: 'philosophersMirror',
            protectAt: null,
            protectionItemHrid: null,
            expectedActions: 0,
            expectedProtects: 0,
            traditionalActions: 0,
            traditionalProtects: 0,
            perActionCost: 0,
            minProtectCost: 0,
            baseItemPrice: 0,
            baseItemCost: 0,
            materialCost: 0,
            protectCost: 0,
            mirrorCount: template.mirrorCount,
            mirrorUnitCost: template.mirrorUnitCost,
            mirrorCost: template.mirrorCount * template.mirrorUnitCost,
            mirrorSource: template.mirrorSource,
            mirrorMarketAsk: template.mirrorMarketAsk,
            mirrorCraftCost: template.mirrorCraftCost,
            mirrorStartLevel: template.mirrorStartLevel,
            mirrorOutputMin: template.mirrorOutputMin,
            normalNeeds: template.normalNeeds,
            refinedNeeds: template.refinedNeeds,
            totalTimeHours: 0,
            exp: 0,
            expPerHour: 0,
            componentDetails: []
        };
        for (const component of selectedComponents) {
            const quantity = component.quantity;
            const plan = component.plan;
            route.baseItemCost += plan.baseItemCost * quantity;
            route.materialCost += plan.materialCost * quantity;
            route.protectCost += plan.protectCost * quantity;
            route.expectedActions += plan.expectedActions * quantity;
            route.expectedProtects += plan.expectedProtects * quantity;
            route.traditionalActions += plan.traditionalActions * quantity;
            route.traditionalProtects += plan.traditionalProtects * quantity;
            route.totalTimeHours += plan.totalTimeHours * quantity;
            route.exp += plan.exp * quantity;
            route.componentDetails.push({
                itemHrid: component.itemHrid,
                level: component.level,
                quantity,
                protectAt: plan.protectAt,
                expectedActions: plan.expectedActions,
                expectedProtects: plan.expectedProtects,
                perActionCost: plan.perActionCost,
                minProtectCost: plan.minProtectCost,
                baseItemCost: plan.baseItemCost,
                baseItemPrice: plan.baseItemPrice
            });
        }
        route.baseItemPrice = route.baseItemCost;
        route.perActionCost = route.expectedActions > 0 ? route.materialCost / route.expectedActions : 0;
        route.minProtectCost = route.expectedProtects > 0 ? route.protectCost / route.expectedProtects : 0;
        route.totalCost = route.baseItemCost + route.materialCost + route.protectCost + route.mirrorCost;
        route.expPerHour = route.totalTimeHours > 0 ? route.exp / route.totalTimeHours : 0;
        return route;
    }

function mooncakeBuildMirrorRouteForObjective(template, price, objective, options = {}) {
        if (objective === 'standard') {
            const standardHourlyWage = Number.isFinite(Number(options.standardHourlyWage))
                ? Math.max(0, Number(options.standardHourlyWage))
                : mooncakeGetEnhancementStandardHourlyWage();
            return mooncakeAggregateMirrorRoute(
                template,
                mooncakePickMirrorComponentPlans(template, standardHourlyWage)
            );
        }
        if (objective === 'minCost' || !(price > 0)) {
            return mooncakeAggregateMirrorRoute(template, mooncakePickMirrorComponentPlans(template, 0));
        }

        let lambda = 0;
        let lastSignature = '';
        let bestRoute = null;
        for (let iteration = 0; iteration < 10; iteration++) {
            const selected = mooncakePickMirrorComponentPlans(template, lambda);
            const signature = selected.map(component => `${component.itemHrid}:${component.level}:${component.plan.protectAt}`).join('|');
            const route = mooncakeAggregateMirrorRoute(template, selected);
            if (!(route.totalTimeHours > 0)) return route;
            const nextLambda = (price * MOONCAKE_MARKET_SELL_NET_FACTOR - route.totalCost) / route.totalTimeHours;
            bestRoute = route;
            if (signature === lastSignature || Math.abs(nextLambda - lambda) < 0.01) break;
            lastSignature = signature;
            lambda = nextLambda;
        }
        return bestRoute;
    }

function mooncakeBuildEnhancementRouteCandidates(itemHrid, targetLevel, marketData, options) {
        const target = Number(targetLevel);
        if (!Number.isInteger(target) || target <= 0 || target > 20 || !options) return null;
        const contextMemo = new Map();
        const getContext = hrid => {
            if (contextMemo.has(hrid)) return contextMemo.get(hrid);
            const context = options.buildCostContext(hrid, marketData);
            contextMemo.set(hrid, context || null);
            return context || null;
        };
        const primaryContext = getContext(itemHrid);
        const traditionalRoutes = primaryContext
            ? mooncakeBuildTraditionalUnitPlans(primaryContext, target)
            : [];
        if (!traditionalRoutes.length) return null;

        const mirrorTemplates = [];
        if (target >= MOONCAKE_MIRROR_OUTPUT_MIN_LEVEL) {
            for (let mirrorOutputMin = MOONCAKE_MIRROR_OUTPUT_MIN_LEVEL; mirrorOutputMin <= target; mirrorOutputMin++) {
                const template = mooncakeBuildMirrorRouteTemplate(
                    itemHrid,
                    target,
                    marketData,
                    options,
                    mirrorOutputMin,
                    getContext
                );
                if (template) mirrorTemplates.push(template);
            }
        }
        return { itemHrid, targetLevel: target, traditionalRoutes, mirrorTemplates };
    }

function mooncakeSelectEnhancementRoute(candidates, price, objective = null, options = {}) {
        if (!candidates?.traditionalRoutes?.length) return null;
        const selectionMode = mooncakeGetEnhancementRouteSelectionMode(objective);
        let minCostRoute = null;
        let highestHourlyRoute = null;
        let standardHourlyRoute = null;

        const selectMinCost = () => {
            if (minCostRoute) return minCostRoute;
            const minCostRoutes = [...candidates.traditionalRoutes];
            for (const template of candidates.mirrorTemplates || []) {
                const route = mooncakeBuildMirrorRouteForObjective(template, price, 'minCost');
                if (route) minCostRoutes.push(route);
            }
            minCostRoute = minCostRoutes.reduce((best, route) => !best || route.totalCost < best.totalCost - MOONCAKE_ROUTE_SELECTION_EPSILON ||
                (Math.abs(route.totalCost - best.totalCost) <= MOONCAKE_ROUTE_SELECTION_EPSILON && route.totalTimeHours < best.totalTimeHours) ? route : best, null);
            return minCostRoute;
        };

        const selectHighestHourly = () => {
            if (highestHourlyRoute) return highestHourlyRoute;
            const hourlyRoutes = [...candidates.traditionalRoutes];
            for (const template of candidates.mirrorTemplates || []) {
                const route = mooncakeBuildMirrorRouteForObjective(template, price, 'maxHourly');
                if (route) hourlyRoutes.push(route);
            }
            const validHourlyRoutes = hourlyRoutes.filter(route => Number(route?.totalTimeHours) > 0);
            if (!validHourlyRoutes.length) return null;
            highestHourlyRoute = validHourlyRoutes.reduce((best, route) => {
                const hourly = (price * MOONCAKE_MARKET_SELL_NET_FACTOR - route.totalCost) / route.totalTimeHours;
                const bestHourly = best ? (price * MOONCAKE_MARKET_SELL_NET_FACTOR - best.totalCost) / best.totalTimeHours : -Infinity;
                return !best || hourly > bestHourly + MOONCAKE_ROUTE_SELECTION_EPSILON ||
                    (Math.abs(hourly - bestHourly) <= MOONCAKE_ROUTE_SELECTION_EPSILON && route.totalCost < best.totalCost) ? route : best;
            }, null);
            return highestHourlyRoute;
        };

        const selectStandardHourly = () => {
            if (standardHourlyRoute) return standardHourlyRoute;
            const standardHourlyWage = Number.isFinite(Number(options.standardHourlyWage))
                ? Math.max(0, Number(options.standardHourlyWage))
                : mooncakeGetEnhancementStandardHourlyWage();
            const standardRoutes = [...candidates.traditionalRoutes];
            for (const template of candidates.mirrorTemplates || []) {
                const route = mooncakeBuildMirrorRouteForObjective(template, price, 'standard', {
                    standardHourlyWage
                });
                if (route) standardRoutes.push(route);
            }
            standardHourlyRoute = mooncakeSelectStandardHourlyRoute(standardRoutes, {
                standardHourlyWage
            });
            return standardHourlyRoute;
        };

        if (selectionMode === 'standard') return selectStandardHourly() || selectMinCost();
        const highestProfit = selectMinCost();
        const highestHourly = selectHighestHourly() || highestProfit;
        // Highest profit and highest hourly remain pure objectives.
        if (selectionMode === 'minCost') return highestProfit;
        return highestHourly;
    }

function mooncakeBuildLegacyTraditionalRoute(itemHrid, targetLevel, marketData, price, options = {}) {
        const routeOptions = options && typeof options === 'object' ? options : {};
        const selectionMode = mooncakeGetEnhancementRouteSelectionMode(routeOptions.objective);
        const best = findBestProtectLevel(itemHrid, targetLevel, marketData, price, {
            ...routeOptions,
            objective: selectionMode
        });
        if (!best || !(best.totalCost > 0)) return null;
        const simulation = Enhancelate(itemHrid, targetLevel, best.protectAt);
        if (!(simulation?.actions > 0)) return null;
        const totalTimeHours = calcEnhancingTimeSeconds(itemHrid, simulation.actions) / 3600;
        if (!(totalTimeHours > 0)) return null;
        const materialCost = best.perActionCost * best.expectedActions;
        const protectCost = best.minProtectCost * best.expectedProtects;
        return {
            routeType: 'traditional',
            routeSelectionPolicy: best.routeSelectionPolicy || null,
            protectAt: best.protectAt,
            protectionItemHrid: best.expectedProtects > 1e-9 ? (getProtectionItems(itemHrid) || [])
                .find(hrid => Number(hostProtectionPrice(itemHrid, hrid, marketData)) === Number(best.minProtectCost)) || null : null,
            expectedActions: best.expectedActions,
            expectedProtects: best.expectedProtects,
            traditionalActions: best.expectedActions,
            traditionalProtects: best.expectedProtects,
            perActionCost: best.perActionCost,
            minProtectCost: best.minProtectCost,
            baseItemPrice: best.baseItemPrice,
            baseItemSource: best.baseItemSource || null,
            baseItemCost: best.baseItemPrice,
            materialCost,
            protectCost,
            mirrorCount: 0,
            mirrorCost: 0,
            totalCost: best.totalCost,
            totalTimeHours,
            exp: Number(simulation.exp) || 0,
            expPerHour: best.expPerHour || 0
        };
    }

function mooncakeBuildGenericEnhancementRouteCandidates(itemHrid, targetLevel, marketData) {
        const characterKey = `${mooncakeCharacterCalcSignature || 'live'}:${JSON.stringify(getPlayerEnhanceParams())}`;
        const key = `${mooncakeMarketPricingRevision}|${characterKey}|${itemHrid}|${targetLevel}`;
        const cached = mooncakeEnhancementRouteCandidateCache.get(key);
        if (cached) {
            mooncakeEnhancementRouteCandidateCache.delete(key);
            mooncakeEnhancementRouteCandidateCache.set(key, cached);
            return cached;
        }
        const candidates = mooncakeBuildEnhancementRouteCandidates(itemHrid, targetLevel, marketData, {
            buildCostContext: mooncakeBuildGenericEnhancementCostContext,
            resolveMirrorUnitCost: mooncakeResolveGenericMirrorUnitCost,
            resolveRefinementMaterialPrice: mooncakeResolveGenericMaterialPrice
        });
        return candidates ? mooncakeCacheEnhancementRouteCandidates(key, candidates) : null;
    }

function mooncakeGetEnhancementRoute(itemHrid, targetLevel, marketData, price, objective = null, options = {}) {
        const target = Number(targetLevel);
        if (!Number.isInteger(target) || target <= 0) return null;
        const selectionMode = mooncakeGetEnhancementRouteSelectionMode(objective);
        if (!(Number(price) > 0) && selectionMode !== 'standard') return null;
        const routeOptions = options && typeof options === 'object' ? options : {};
        const isRefined = String(itemHrid || '').endsWith('_refined');
        // 精炼白板的市场价和自制价已在白板成本中比较；精炼装备本身仍按保护等级选路线。
        if (target < MOONCAKE_MIRROR_OUTPUT_MIN_LEVEL && !isRefined) {
            return mooncakeBuildLegacyTraditionalRoute(itemHrid, target, marketData, price, {
                ...routeOptions,
                objective: selectionMode
            });
        }
        const candidates = mooncakeBuildGenericEnhancementRouteCandidates(itemHrid, target, marketData);
        if (!candidates?.mirrorTemplates?.length && !isRefined) {
            return mooncakeBuildLegacyTraditionalRoute(itemHrid, target, marketData, price, {
                ...routeOptions,
                objective: selectionMode
            });
        }
        const route = mooncakeSelectEnhancementRoute(candidates, Number(price), selectionMode, routeOptions);
        return route || mooncakeBuildLegacyTraditionalRoute(itemHrid, target, marketData, price, {
            ...routeOptions,
            objective: selectionMode
        });
    }

function mooncakeCalculateEnhancementRouteAtPrice(itemHrid, targetLevel, marketData, price, objective = null) {
        const route = mooncakeGetEnhancementRoute(itemHrid, targetLevel, marketData, price, objective);
        if (!route || !(route.totalTimeHours > 0)) return null;
        return {
            ...route,
            hourlyWage: (Number(price) * MOONCAKE_MARKET_SELL_NET_FACTOR - route.totalCost) / route.totalTimeHours
        };
    }

function mooncakeNormalizeEnhancementRouteCostBreakdown(route) {
        if (!route || typeof route !== 'object') return route;
        const normalized = { ...route };
        const numberOrNull = value => Number.isFinite(Number(value)) ? Number(value) : null;
        const expectedActions = numberOrNull(normalized.expectedActions);
        const expectedProtects = numberOrNull(normalized.expectedProtects);
        const perActionCost = numberOrNull(normalized.perActionCost);
        const minProtectCost = numberOrNull(normalized.minProtectCost);
        const totalCost = numberOrNull(normalized.totalCost);
        const materialCost = numberOrNull(normalized.materialCost);
        const protectCost = numberOrNull(normalized.protectCost);
        const mirrorCost = numberOrNull(normalized.mirrorCost) || 0;

        normalized.materialCost = materialCost !== null
            ? materialCost
            : (expectedActions !== null && perActionCost !== null ? expectedActions * perActionCost : 0);
        normalized.protectCost = protectCost !== null
            ? protectCost
            : (expectedProtects !== null && minProtectCost !== null ? expectedProtects * minProtectCost : 0);
        if (numberOrNull(normalized.baseItemCost) === null && totalCost !== null) {
            normalized.baseItemCost = Math.max(0, totalCost - normalized.materialCost - normalized.protectCost - mirrorCost);
        }
        return normalized;
    }

function mooncakeBuildEnhancementRouteObjectiveEntry(route, price) {
        if (!route) return null;
        const normalizedRoute = mooncakeNormalizeEnhancementRouteCostBreakdown(route);
        const totalTimeHours = Number(normalizedRoute.totalTimeHours);
        const totalCost = Number(normalizedRoute.totalCost);
        const sellPrice = Number(price);
        const netRevenue = sellPrice * MOONCAKE_MARKET_SELL_NET_FACTOR;
        const profit = Number.isFinite(totalCost) && Number.isFinite(netRevenue)
            ? netRevenue - totalCost
            : null;
        return {
            ...normalizedRoute,
            sellPrice,
            totalTimeHours,
            profit,
            profitMargin: totalCost > 0 && Number.isFinite(profit) ? profit / totalCost : null,
            hourlyWage: totalTimeHours > 0 && Number.isFinite(profit) ? profit / totalTimeHours : null
        };
    }

function mooncakeGetEnhancementRouteSignature(route) {
        if (!route) return '';
        const number = value => Number.isFinite(Number(value)) ? Number(value).toPrecision(12) : '';
        const components = Array.isArray(route.componentDetails)
            ? route.componentDetails.map(component => ({
                itemHrid: String(component?.itemHrid || ''),
                level: number(component?.level),
                quantity: number(component?.quantity),
                protectAt: number(component?.protectAt)
            })).sort((left, right) => JSON.stringify(left).localeCompare(JSON.stringify(right)))
            : [];
        return JSON.stringify({
            routeType: String(route.routeType || ''),
            protectAt: number(route.protectAt),
            protectionItemHrid: String(route.protectionItemHrid || ''),
            mirrorStartLevel: number(route.mirrorStartLevel),
            mirrorOutputMin: number(route.mirrorOutputMin),
            mirrorSource: String(route.mirrorSource || ''),
            refinementAtLevel: number(route.refinementAtLevel),
            refinementCost: number(route.refinementCost),
            baseItemCost: number(route.baseItemCost),
            materialCost: number(route.materialCost),
            protectCost: number(route.protectCost),
            mirrorCost: number(route.mirrorCost),
            totalCost: number(route.totalCost),
            expectedActions: number(route.expectedActions),
            expectedProtects: number(route.expectedProtects),
            components
        });
    }

function mooncakeResolveObjectiveRoutePair(itemHrid, targetLevel, marketData, price, selectedRoute = null) {
        const target = Number(targetLevel);
        const selectedPrice = Number(price);
        if (!itemHrid || !Number.isInteger(target) || target <= 0 || !(selectedPrice > 0)) return null;

        const selectedObjective = getEnhancementRouteObjective();
        const sourceMarketData = marketData || getMarketData();
        const characterKey = `${mooncakeCharacterCalcSignature || 'live'}:${JSON.stringify(getPlayerEnhanceParams())}`;
        const canUseCache = sourceMarketData?.marketData === marketDataCache;
        const standardHourlyWage = mooncakeGetEnhancementStandardHourlyWage();
        const cacheKey = `${mooncakeMarketPricingRevision}|${characterKey}|${itemHrid}|${target}|${selectedPrice}|${standardHourlyWage}`;
        let routes = canUseCache ? mooncakeEnhancementRoutePairCache.get(cacheKey) : null;

        if (!routes) {
            const highestHourly = mooncakeBuildEnhancementRouteObjectiveEntry(
                mooncakeGetEnhancementRoute(itemHrid, target, sourceMarketData, selectedPrice, 'hourly'),
                selectedPrice
            );
            const highestProfit = mooncakeBuildEnhancementRouteObjectiveEntry(
                mooncakeGetEnhancementRoute(itemHrid, target, sourceMarketData, selectedPrice, 'profit'),
                selectedPrice
            );
            const standardHourly = mooncakeBuildEnhancementRouteObjectiveEntry(
                mooncakeGetEnhancementRoute(itemHrid, target, sourceMarketData, selectedPrice, 'standard', {
                    standardHourlyWage
                }),
                selectedPrice
            );
            if (!highestHourly && !highestProfit && !standardHourly) return null;
            routes = { highestHourly, highestProfit, standardHourly };
            if (canUseCache) {
                mooncakeSetBoundedMapEntry(
                    mooncakeEnhancementRoutePairCache,
                    cacheKey,
                    routes,
                    MOONCAKE_ENHANCEMENT_ROUTE_PAIR_CACHE_LIMIT
                );
            }
        } else {
            mooncakeEnhancementRoutePairCache.delete(cacheKey);
            mooncakeEnhancementRoutePairCache.set(cacheKey, routes);
        }

        const rawSelected = selectedObjective === 'profit'
            ? routes.highestProfit
            : (selectedObjective === 'standard' ? routes.standardHourly : routes.highestHourly);
        let selected = mooncakeBuildEnhancementRouteObjectiveEntry(selectedRoute, selectedPrice) ||
            mooncakeBuildEnhancementRouteObjectiveEntry(
                mooncakeGetEnhancementRoute(itemHrid, target, sourceMarketData, selectedPrice, selectedObjective),
                selectedPrice
            ) || rawSelected;
        let alternateObjective = selectedObjective === 'profit' ? 'hourly' : 'profit';
        let expectedAlternate = selectedObjective === 'profit' ? routes.highestHourly : routes.highestProfit;
        const standardHourlyPolicy = selected?.routeSelectionPolicy?.type === 'standard-hourly-equivalent-cost'
            ? selected.routeSelectionPolicy
            : null;
        if (standardHourlyPolicy) {
            const policyHourlyWage = Number.isFinite(Number(standardHourlyPolicy.standardHourlyWage))
                ? Number(standardHourlyPolicy.standardHourlyWage)
                : standardHourlyWage;
            const withEquivalentCost = entry => entry
                ? {
                    ...entry,
                    standardHourlyWage: policyHourlyWage,
                    equivalentCost: mooncakeGetRouteEquivalentCost(entry, policyHourlyWage)
                }
                : null;
            selected = withEquivalentCost(selected);
            expectedAlternate = withEquivalentCost(
                mooncakeBuildEnhancementRouteObjectiveEntry(
                    standardHourlyPolicy.alternateRoute,
                    selectedPrice
                )
            );
            alternateObjective = 'standard';
        }
        const selectedSignature = mooncakeGetEnhancementRouteSignature(selected);
        const alternateSignature = mooncakeGetEnhancementRouteSignature(expectedAlternate);
        const hasAlternative = !!selected && !!expectedAlternate && selectedSignature !== alternateSignature;

        return {
            targetLevel: target,
            selectedObjective,
            alternateObjective,
            selected,
            alternate: hasAlternative ? expectedAlternate : null,
            standardHourlyPolicy,
            highestHourly: routes.highestHourly,
            highestProfit: routes.highestProfit,
            standardHourly: routes.standardHourly,
            hasAlternative
        };
    }

let mooncakeRefinementRelationIndex = null;

const MOONCAKE_MARKET_PRICE_TIERS = [
            { max: 500, step: 1, offset: 0 },
            { max: 1000, step: 2, offset: 500 },
            { max: 3000, step: 5, offset: 1000 },
            { max: 5000, step: 10, offset: 3000 },
            { max: 10000, step: 20, offset: 5000 },
            { max: 30000, step: 50, offset: 10000 },
            { max: 50000, step: 100, offset: 30000 },
            { max: 100000, step: 200, offset: 50000 },
            { max: 300000, step: 500, offset: 100000 },
            { max: 500000, step: 1000, offset: 300000 },
            { max: 1000000, step: 2000, offset: 500000 },
            { max: 3000000, step: 5000, offset: 1000000 },
            { max: 5000000, step: 10000, offset: 3000000 },
            { max: 10000000, step: 20000, offset: 5000000 },
            { max: 30000000, step: 50000, offset: 10000000 },
            { max: 50000000, step: 100000, offset: 30000000 },
            { max: 100000000, step: 200000, offset: 50000000 },
            { max: 300000000, step: 500000, offset: 100000000 },
            { max: 500000000, step: 1000000, offset: 300000000 },
            { max: 1000000000, step: 2000000, offset: 500000000 },
            { max: 3000000000, step: 5000000, offset: 1000000000 },
            { max: 5000000000, step: 10000000, offset: 3000000000 },
            { max: 10000000000, step: 20000000, offset: 5000000000 },
            { max: 30000000000, step: 50000000, offset: 10000000000 },
            { max: 50000000000, step: 100000000, offset: 30000000000 }
    ];

function mooncakeGetMarketPriceTier(price) {
        const num = Math.abs(Number(price));
        if (!Number.isFinite(num)) return null;
        const tier = MOONCAKE_MARKET_PRICE_TIERS.find(item => num < item.max);
        if (tier) return tier;

        // Continue the game's leading-digit progression above the explicit
        // common ranges instead of freezing prices above 50B on one step.
        const integer = Math.max(1, Math.floor(num));
        const digits = Math.floor(Math.log10(integer)) + 1;
        const magnitude = Math.pow(10, digits - 1);
        const leadingDigit = Math.floor(integer / magnitude);
        if (leadingDigit <= 2) {
            return {
                max: 3 * magnitude,
                step: Math.max(1, 5 * Math.pow(10, digits - 4)),
                offset: magnitude
            };
        }
        if (leadingDigit <= 4) {
            return {
                max: 5 * magnitude,
                step: Math.max(1, Math.pow(10, digits - 3)),
                offset: 3 * magnitude
            };
        }
        return {
            max: 10 * magnitude,
            step: Math.max(1, 2 * Math.pow(10, digits - 3)),
            offset: 5 * magnitude
        };
    }

function mooncakeSnapMarketPrice(price, direction = 'down') {
        const num = Number(price);
        if (!Number.isFinite(num) || num <= 0) return 0;
        const tier = mooncakeGetMarketPriceTier(num);
        if (!tier) return 0;
        const rawIndex = (num - tier.offset) / tier.step;
        const epsilon = 1e-9;
        const index = direction === 'up'
            ? Math.ceil(rawIndex - epsilon)
            : Math.floor(rawIndex + epsilon);
        return Math.max(1, tier.offset + Math.max(0, index) * tier.step);
    }

function mooncakeGetRefinementRelationIndex() {
        const actionDetailMap = getInitClientData()?.actionDetailMap || null;
        if (!actionDetailMap) return null;
        if (mooncakeRefinementRelationIndex?.source === actionDetailMap) return mooncakeRefinementRelationIndex;

        const byBase = new Map();
        const byRefined = new Map();
        const byShard = new Map();
        for (const [actionHrid, actionDetail] of Object.entries(actionDetailMap)) {
            if (!Array.isArray(actionDetail?.outputItems)) continue;
            const refinedOutputs = actionDetail.outputItems
                .filter(output => String(output?.itemHrid || '').endsWith('_refined'));
            if (!refinedOutputs.length) continue;
            const shardInputs = (actionDetail.inputItems || [])
                .filter(input => String(input?.itemHrid || '').endsWith('_refinement_shard'))
                .map(input => ({
                    itemHrid: input.itemHrid,
                    rawCount: Math.max(0, Number(input.count) || 0)
                }))
                .filter(input => input.itemHrid && input.rawCount > 0);
            if (!shardInputs.length) continue;

            for (const output of refinedOutputs) {
                const refinedHrid = output.itemHrid;
                const baseHrid = actionDetail.upgradeItemHrid || String(refinedHrid).replace(/_refined$/, '');
                if (!baseHrid || !refinedHrid) continue;
                const relation = {
                    actionHrid,
                    actionDetail,
                    baseHrid,
                    refinedHrid,
                    outputCount: Math.max(1, Number(output.count) || 1),
                    shardInputs
                };
                if (!byBase.has(baseHrid)) byBase.set(baseHrid, relation);
                if (!byRefined.has(refinedHrid)) byRefined.set(refinedHrid, relation);
                for (const input of shardInputs) {
                    if (!byShard.has(input.itemHrid)) byShard.set(input.itemHrid, []);
                    byShard.get(input.itemHrid).push(relation);
                }
            }
        }
        mooncakeRefinementRelationIndex = { source: actionDetailMap, byBase, byRefined, byShard };
        return mooncakeRefinementRelationIndex;
    }

function mooncakeNormalizeRefinementBaseHrid(hrid) {
        const value = String(hrid || '');
        return value.endsWith('_refined') ? value.replace(/_refined$/, '') : value;
    }

function mooncakeGetRefinementActionForItem(hrid) {
        const baseHrid = mooncakeNormalizeRefinementBaseHrid(hrid);
        const index = mooncakeGetRefinementRelationIndex();
        const relation = String(hrid || '').endsWith('_refined')
            ? (index?.byRefined.get(String(hrid || '')) || index?.byBase.get(baseHrid))
            : index?.byBase.get(baseHrid);
        return relation || null;
    }

function getPriceTier(price, direction) {
        const currentPrice = mooncakeSnapMarketPrice(price, 'down');
        if (!(currentPrice > 0)) return 0;
        if (direction === 'up') {
            return mooncakeSnapMarketPrice(currentPrice + 1, 'up');
        }
        return mooncakeSnapMarketPrice(currentPrice - 1, 'down');
    }
    // Host acquisition policy: change inputs to the upstream probability and
    // route formulas, never their arithmetic. Missing purchase quotes use a
    // known crafting cost; a missing crafting cost is never treated as free.
    const resolveAutomaticBase = mooncakeResolveGenericBaseItemPrice;
    mooncakeResolveGenericBaseItemPrice = (hrid, data) => {
      const result = resolveAutomaticBase(hrid, data);
      if (!["market", "craft"].includes(acquisitionSource)) return result;
      const source = acquisitionSource === "market" && !(result.productPrice > 0) && result.craftingCost > 0
        ? "craft" : acquisitionSource;
      return { ...result, source,
        price: source === "craft" ? result.craftingCost : result.productPrice };
    };
    function hostProtectionPrice(itemHrid, protectHrid, data) {
      return acquisitionSource && itemHrid === protectHrid
        ? mooncakeResolveGenericBaseItemPrice(itemHrid, data).price
        : getMarketPrice(protectHrid, data);
    }
    // An explicit +0 acquisition choice cannot be replaced by enhancing an
    // unrefined item and refining it later. Unselected legacy routes are intact.
    const carryoverPlans = mooncakeBuildRefinementCarryoverPlans;
    mooncakeBuildRefinementCarryoverPlans = (...args) =>
      ["market", "craft"].includes(acquisitionSource) ? [] : carryoverPlans(...args);
    // Host-only observation: preserve the exact upstream aggregation and retain
    // the selected component plans for material quantities, including carryover
    // provenance and protection HRIDs that upstream componentDetails omits.
    const aggregateMirrorRoute = mooncakeAggregateMirrorRoute;
    mooncakeAggregateMirrorRoute = (template, components) => ({
      ...aggregateMirrorRoute(template, components),
      materialComponents: components.map(({ itemHrid, quantity, plan }) => ({ ...plan, itemHrid, quantity }))
    });
    // Host-only comparison adapter. Select the recorded recipe/protection/source
    // and reuse the original unit-plan and aggregation functions verbatim.
    // No upstream probability, cost, timing, or optimization formula is changed.
    function hostFixedUnit(hrid, level, original, exactLevel = false) {
      const carryover = original.routeType === "refinementCarryover";
      const relation = carryover ? mooncakeGetRefinementActionForItem(hrid) : null;
      if (carryover && !relation) return null;
      const sourceHrid = carryover ? relation.baseHrid : hrid;
      const context = mooncakeBuildEnhancementCostContext(sourceHrid, market, {
        resolveMaterialPrice: mooncakeResolveGenericMaterialPrice,
        resolveProtectionPrice: protectHrid => protectHrid === original.protectionItemHrid
          ? hostProtectionPrice(sourceHrid, protectHrid, market) : 0,
        resolveBaseItemPrice: () => {
          const base = mooncakeResolveGenericBaseItemPrice(sourceHrid, market);
          return { source: original.baseItemSource, price: original.baseItemSource === "craft" ? base.craftingCost
            : original.baseItemSource === "market" ? base.productPrice : base.price };
        }
      });
      if (!context) return null;
      const plan = mooncakeBuildTraditionalUnitPlans(context, level, { exactLevel })
        .find(candidate => candidate.protectAt === original.protectAt);
      if (!plan) return null;
      if (!carryover) return plan;
      const refinementCost = mooncakeCalculateRefinementCarryoverCost(relation, market, mooncakeResolveGenericMaterialPrice);
      return mooncakeBuildRefinementCarryoverPlans([plan], refinementCost, original.refinementAtLevel)[0] || null;
    }
    function hostFixedRoute(hrid, level, original) {
      if (!original) return null;
      if (["traditional", "refinementCarryover"].includes(original.routeType)) return hostFixedUnit(hrid, level, original);
      if (original.routeType !== "philosophersMirror" || !original.materialComponents?.length) return null;
      const mirror = mooncakeResolveGenericMirrorUnitCost(market);
      const unitCost = original.mirrorSource === "craft" ? mirror?.craftCost : mirror?.marketAsk;
      if (!(unitCost > 0)) return null;
      const components = original.materialComponents.map((component, index) => ({
        itemHrid: component.itemHrid, level: original.componentDetails?.[index]?.level, quantity: component.quantity,
        plan: hostFixedUnit(component.itemHrid, original.componentDetails?.[index]?.level, component, true)
      }));
      if (components.some(component => !component.plan)) return null;
      return mooncakeAggregateMirrorRoute({ ...original, mirrorUnitCost: unitCost }, components);
    }
    return Object.freeze({
      fixedRoute: hostFixedRoute,
      // Read-only host adapters: expose existing solvers without changing formulas.
      secondsPerAction: calcEnhancingSecondsPerAction,
      enhancementExpectation: Enhancelate,
      saleNetFactor: MOONCAKE_MARKET_SELL_NET_FACTOR,
      enhancingDrinkHrids: () => [...mooncakeGetEnhancingDrinkHrids()],
      // Host-only inventory preparation readout. Reuse the upstream Markov
      // simulation at its supported starting level; never value owned gear at
      // zero in the market profitability calculation below.
      continuation: (hrid, level, startLevel, selectedProtectAt = null) => {
        if (!Number.isInteger(startLevel) || startLevel < 0 || startLevel >= level || level > 20) return null;
        const context = mooncakeBuildEnhancementCostContext(hrid, market, {
          resolveMaterialPrice: mooncakeResolveGenericMaterialPrice,
          resolveProtectionPrice: protectHrid => hostProtectionPrice(hrid, protectHrid, market),
          resolveBaseItemPrice: () => ({ price: 1, source: "craft" })
        });
        if (!context) return null;
        let best = null;
        for (let protectAt = level === 1 ? 1 : 2; protectAt <= level; protectAt++) {
          if (selectedProtectAt != null && protectAt !== selectedProtectAt) continue;
          const sim = Enhancelate(hrid, level, protectAt, null, startLevel);
          if (!(sim.actions > 0) || !Number.isFinite(sim.actions) || !Number.isFinite(sim.protectCount) ||
              sim.protectCount > 1e-9 && !(context.minProtectCost > 0)) continue;
          const cost = context.perActionCost * sim.actions + context.minProtectCost * sim.protectCount;
          if (!best || cost < best.remainingCost) best = {
            routeType: "traditional", startLevel, protectAt, baseItemSource: "craft",
            protectionItemHrid: sim.protectCount > 1e-9 ? context.protectionItemHrid : null,
            expectedActions: sim.actions, expectedProtects: sim.protectCount,
            totalTimeHours: context.secondsPerAction * sim.actions / 3600, remainingCost: cost
          };
        }
        return best;
      },
      calculate: (hrid, level, price) => calcHourlyWageAndMetrics(hrid, level, market, price),
      // Host-only preparation readout. The upstream entry requires a positive
      // price, but 'profit' selects minimum total cost independently of it.
      // This neutral internal argument is never exposed as a market quote.
      minimumCostRoute: (hrid, level) => mooncakeGetEnhancementRoute(hrid, level, market, 1, 'profit'),
      acquisition: hrid => ({ ...mooncakeResolveGenericBaseItemPrice(hrid, market) }),
      compareBase: (hrid, price) => mooncakeCalculateLevelZeroMarketComparison(hrid, "sell", price, market),
      // Host-only readout. Reuse upstream price resolvers without altering formulas.
      simulationPriceInfo: (hrid) => {
        const sources = mooncakeGetBaseItemCostPricePolicy().material;
        const source = sources.find(side => mooncakeGetBaseItemCostPolicyQuote(hrid, market, side) > 0);
        return {
          ask: mooncakeGetMarketAskPrice(hrid, market), bid: mooncakeGetMarketBidPrice(hrid, market),
          enhancement: mooncakeResolveGenericMaterialPrice(hrid, market),
          protection: getMarketPrice(hrid, market),
          basePurchase: mooncakeGetBaseItemCostPolicyQuote(hrid, market, mooncakeGetBaseItemCostPricePolicy().product),
          basePurchaseSource: mooncakeGetBaseItemCostPricePolicy().product,
          manufacturingQuote: source ? mooncakeGetBaseItemCostPolicyQuote(hrid, market, source) : 0,
          manufacturingSource: source || null,
          mirror: hrid === MOONCAKE_PHILOSOPHERS_MIRROR_HRID ? mooncakeResolveGenericMirrorUnitCost(market)?.unitCost : null
        };
      },
      // Read-only decomposition for ordinary direct recipes. Charm plans can
      // buy fractional upstream batches, so do not invent a per-input split.
      simulationManufacturingPrices: (hrid) => {
        const context = mooncakeCreateBaseItemCostCraftingContext();
        if (!context.materialPriceSources.length || mooncakeIsCraftableCharmTier(hrid, context)) return {};
        const totals = new Map();
        const processed = new Set([hrid]);
        const multiplier = mooncakeGetRecipeMaterialMultiplier(hrid, context.artisanMultiplier);
        for (const input of getCraftingRecipe(hrid)?.inputs || []) {
          const charm = mooncakeResolveCharmUpgradeInputCost(hrid, input, market, processed, context);
          const marketPrice = mooncakeResolveCraftingContextMarketPrice(context, input.itemHrid, market);
          const craft = hrid.includes('_refined') || !(marketPrice > 0)
            ? getCraftingCost(input.itemHrid, market, processed, context) : 0;
          const price = charm ? charm.price : hrid.includes('_refined')
            ? mooncakeChooseLowerPositiveCost(marketPrice, craft) : marketPrice > 0 ? marketPrice : craft;
          const count = input.count * (input.isFixedUpgradeItem ? 1 : multiplier);
          const total = totals.get(input.itemHrid) || { count: 0, cost: 0, valid: true };
          total.valid &&= price > 0 && count > 0;
          total.count += count; total.cost += price * count;
          totals.set(input.itemHrid, total);
        }
        return Object.fromEntries([...totals].map(([hrid, total]) => [hrid, total.valid ? total.cost / total.count : null]));
      },
      params: getPlayerEnhanceParams,
      artisanMaterialMultiplier: mooncakeGetArtisanMaterialMultiplier,
      drinkConcentrationBonus: getDrinkConcentrationBonus,
      recipe: getCraftingRecipe,
      enhancementCosts: getEnhancementCosts,
      protectionItems: getProtectionItems,
      defaults: { virtual: DEFAULT_VIRTUAL_CONFIG, colors: MOONCAKE_DEFAULT_HOURLY_WAGE_COLOR_PROFILE },
      normalizeColors: mooncakeNormalizeHourlyWageColorProfile,
      normalizePolicy: mooncakeNormalizeBaseItemCostPricePolicy
    });
  }
  app.wageEngine = Object.freeze({ create });
})(globalThis);


