(function initBackupUI(root){"use strict";const app=root.MWILayuEnhancement=root.MWILayuEnhancement||{};const t=(text,...values)=>app.i18n?app.i18n.t(text,...values):typeof text==="string"?text:text.reduce((out,part,i)=>out+part+(i<values.length?values[i]:""),"");function create(createStatus){const document=root.document;const backup=app.localBackup.create();const section=document.createElement("details");section.className="mwi-layu-backup";app.viewPreferences.bindDetails(section,"backup");const title=document.createElement("summary");title.textContent=t("本地备份与恢复");const status=createStatus?createStatus():document.createElement("p");status.setAttribute("role","status");const preview=document.createElement("div");function button(text,action){const el=document.createElement("button");el.type="button";el.textContent=text;el.onclick=action;return el}const exportButton=button(t("导出本地备份"),()=>{try{const blob=new root.Blob([backup.serialize()],{type:"application/json"});const url=root.URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download=`layu-backup-${(new Date).toISOString().slice(0,10)}.json`;link.click();root.setTimeout(()=>root.URL.revokeObjectURL(url),1e3);status.textContent=t("已生成本地备份文件。")}catch(error){status.textContent=t`导出失败：${error.message}`}});const label=document.createElement("label");label.textContent=t("选择备份文件 ");const input=document.createElement("input");input.type="file";input.accept=".json,application/json";input.setAttribute("aria-label",t("选择本地备份文件"));label.append(input);let generation=0;input.onchange=async()=>{const current=++generation;preview.replaceChildren();status.textContent="";const file=input.files?.[0];if(!file)return;try{if(file.size>app.localBackup.limits.bytes)throw new Error(t("文件超过 2 MiB，请选择插件导出的备份"));const plan=backup.preview(await file.text());if(current!==generation)return;const summary=document.createElement("p");summary.textContent=t`将恢复 ${plan.totalKeys} 项本地数据。仅覆盖文件内同名数据；未包含的数据保留。备料车按文件中的角色 ID 恢复。`;const list=document.createElement("ul");for(const entry of plan.entries){const row=document.createElement("li");row.textContent=`${entry.label}：${entry.willOverwrite?t("覆盖现有"):t("新增")}${entry.empty?t(" · 空数据将清空该项"):""}`;list.append(row)}const apply=button(t("确认覆盖并刷新游戏"),()=>{try{apply.disabled=true;backup.restore(plan);status.textContent=t("恢复成功，正在刷新游戏以载入设置。");root.location.reload()}catch(error){status.textContent=t`恢复失败：${error.message}`;apply.disabled=false}});const cancel=button(t("取消恢复"),()=>{++generation;preview.replaceChildren();input.value="";status.textContent=t("已取消，数据未改动。");input.focus()});preview.append(summary,list,apply,cancel);status.textContent=t("校验通过，请检查覆盖范围后再恢复。")}catch(error){if(current===generation)status.textContent=t`无法读取备份：${error.message}`}};section.append(title,exportButton,label,preview);if(!createStatus)section.prepend(status);return section}app.backupUI=Object.freeze({create:create})})(globalThis);

// ---- src/ui/settings-help.js ----
(function initSettingsHelp(root){"use strict";const app=root.MWILayuEnhancement=root.MWILayuEnhancement||{};const t=text=>app.i18n?.t(text)??text;const sections=[{title:"强化计划",paragraphs:["按计划顺序扣除共用库存，缺料项计入可支撑的部分时间，再继续计算后续项目。仅计已到账材料与金币，不计待到账、采购或备料倍率，不含制造及等待时间。强化有随机性，实际时长会有差异。","行内成功率和材料可支撑时间按当前已到账库存估算：前项按期望消耗预留，不足时预留可支撑部分；本项按剩余库存中最先耗尽的材料反推。成功率采用指数／Gamma 近似，不是队列整体成功率，保护材料的实际随机消耗可能有偏差。","自动同步游戏中的强化动作，每条动作单独显示并按 1 件核算。顺序、起始等级、目标与保护设置以队列为准；重复次数不是装备件数。","手动添加和填写，可调整数量、等级与顺序。旧版已保存的计划保留在此；如与队列重复且不需额外强化，请手动移除。","合计按队列计划在前、队列外计划在后的顺序核算，共用库存只扣除一次。","仅核算普通强化耗材与保护材料，不含底子制造或镜子、精炼路线。与备料车分别核算，共用的库存不能视为已被两个清单同时预留。","待到账只抵扣采购缺口，不表示已备齐。采购前重新核算库存、买单与余额；仅预填，由你确认交易。倍率备料不保证全部强化成功。","按顺序先备齐前项；不足时仅为当前项按比例备料，停止向后分配。备料比例不代表强化成功率。"]},{title:"备料与库存",paragraphs:["需求仅按备料车累计，制造与强化共用材料统一扣减库存。","按备料车顺序分配共享库存；待到账不算备齐。底子就绪不代表强化耗材齐全，请查看备料车材料表。","强化备料 = 单件路线期望消耗 × 目标数量 × 倍率，按材料汇总后向上取整。包含实际保护物和贤者之镜；默认 1.2，期望值不保证实际够用。","按当前左一估算路线的期望消耗备料，非保证用量；不同等级独立对照库存。","备料车将同装备各目标等级的件数合并，统一抵扣未强化（+0）库存，只为不足的件数计算制造用量；已有强化装备不抵扣。项目明细仍显示新增制作的配方用量，未加入备料车时按 1 件预览。","制造按直接配方和整批次数计算，保留小数用量；详情按物品合并制造与强化用量，需备显示合计，还缺统一扣除一次库存。制造与强化初始计价相同时共用调价控件，不同时在同一行分别显示；已显示的调价控件在本次模拟中保持可见。镜子路线的组成装备需另行备齐，制造用量仍为目标装备的直接配方。","没有目标售价时，备料和准备强化按最低成本路线计算，利润与工时费仍保持售价未知；有售价时恢复所选路线目标。材料、底子或保护物价格缺失时仍可能无法计算。","备料车中某个项目方案未就绪时，已算出的材料仍会保留；数量中的「+ 未知」表示还有未计入部分，不是完整需求。库存足够覆盖已算部分也不代表整车备齐。","启用工匠茶时按角色饮料浓度估算制造减耗，可在设置关闭；升级底子不减耗。"]},{title:"收藏与分区",paragraphs:["按物品和强化等级独立归属；全部取消后退回未分区。","点击刷新价格与库存即可更新全市场买卖一价；本人挂单在打开游戏我的挂单时自动保存。","收藏中的资源材料默认归入此区，同时汇集备料车及收藏项目的直接制造、强化和保护材料；相同物品和等级合并。未加入备料车的项目不计入需备数量。","点击物品旁的收藏按钮保存物品与等级；参考售价可以单独填写。收藏已有挂单商品可导入现有挂单，以后新挂单会自动收藏。","物品可同时属于多个分区，分区归属按物品和强化等级独立保存。全部取消则归入未分区；删除分区保留其他归属。管理列表按游戏编号升序排列。","点击表头切换升降序，未知值始终置底；我的挂单按本人最低挂单价排序。","拖动调节列宽；双击或 Enter 恢复默认；方向键调节，Esc 取消拖动。"]},{title:"行情与挂单",paragraphs:["同价订单越靠下越早；先后未知的订单单独列出。仅显示已读取订单。","左一／右一价格可对照买卖挂单；同价只表示价格相同，不代表同价队列第一。完整订单可在项目明细查看。","区间外按报价估算，低于下限的卖单实际按区间下限执行。左一非现档时保留原价参考。"]},{title:"预设与收藏管理",paragraphs:["隐藏 1–65 级生活工具、基础奶酪与木材系列装备，以及粗糙、爬行动物、哥布林、野兽、暗影皮革系列装备；另隐藏 40 级哥布林装备及棉、亚麻、竹、丝绸、光辉基础布料装备，以及指定的 12 件低中阶装备及小、中、大、巨大四种袋子。保留高阶皮革装备、80/90 级工具及所有精制版。开启时取消被隐藏物品的本次勾选，关闭后不恢复勾选；已有收藏不变。","等级可多选；不可强化物品仅加入 +0。","两个按钮使用相同物品与强化等级条件：仅删预设新增，或删除全部匹配。删除同时移除参考价，可撤销；分区、备料车及游戏挂单保持原状。","仅添加所选物品；保留已有分区归属、收藏与参考价。","组合筛选物品、等级与来源，支持撤销最近一次删除。","筛选条件同时生效；改变条件会清空勾选。删除同时移除参考价，可撤销最近一次删除。分区、备料车及游戏挂单保持原状。","一键清理覆盖全部分区与强化等级，仅删除明确由预设新增的收藏；旧收藏及预设复用的已有收藏保留。"]},{title:"掉落与经验",paragraphs:["启用插件后，自动保存当前浏览器收到的记录，不限 20 条。同一活动保留最新累计值。打开游戏原生记录页或点击其刷新按钮可获取最新数据；已被游戏删除且从未采集的记录无法补回。","仅保存在当前浏览器，按服务器和角色隔离。清理网站数据会丢失存档，建议定期导出备份。"]},{title:"计算与路线",paragraphs:["与月饼相同的强化计算口径：售价扣除 4% 税，再减期望成本、除以强化小时。材料按市场机会成本计价，库存不抵扣；不包含交易等待时间。","自制材料依次尝试以下报价，与成品 +0 报价比较，取较低完整路径。全部选择“不使用”可停用自制路线。","按当前价格与角色参数选择最低总成本方案；次数为期望值，可能与工时费所选方案不同。","耗时不含制造、排队与等待成交；利润和成本沿用当前路线。","列表默认按市场左一出售价估算。利润 = 税后售价 − 总成本；利润率 = 税后利润 ÷ 总成本。价格阶梯按每一档售价和当前角色参数重新估算。","项目明细的材料名称下显示当前模拟单价。左右按钮按该材料 +0 的价格档位减一档、加一档，悬停可看下一档报价；点击后立即更新展开区的利润、利润率、工时费及模拟路线备料。不同收藏等级独立模拟；收藏主行、展开摘要、售价档位和卖单工时费同步标注模拟收益。备料车仍按真实行情计算。","首次打开项目明细截取行情、成品售价和角色参数。材料行可点击“恢复当前左一价格”，将该计价使用的报价恢复为插件最新已读取的 +0 左一价格，仅影响当前材料；缺少有效左一价时按钮不可用。强化与保护按实际单价显示，自制材料按直接配方采用的计价显示；报价与计价可能因自制比较而不同，复杂组合配方无法逐项分摊时显示未知。引擎按原有报价顺位、制造/购买比较和路线目标重新选择方案，候选材料调价可能不影响最终成本。","模拟仅计算单件期望值，不使用备料倍率或向上取整的备料数量。变化含重新选择路线的影响。零价不表示免费，缺价显示未知。金币等固定成本沿用原公式。","模拟不会修改真实行情、参考售价、库存或挂单；输入仅保留在当前页面，刷新游戏或确认切换角色后清空。自动刷新角色参数、库存、行情不会清空当前模拟；新角色参数在刷新页面后重新截取。恢复左一只更新对应材料报价，保留其他材料调整、成品售价与基准参数。缺价或达到档位边界时，对应换档按钮不可用。","强化预填按当前行情方案执行；模拟方案仅用于比较。"]},{title:"备料车与预算",paragraphs:["按当前左一估算缺口，采购数量向上取整；金币直接消耗只计一次。预算不改变工时费成本。","制造按直接配方，强化为期望备料；同材料合并，库存统一扣一次。","金币不足时，可点击「按当前金币分配采购」查看整数采购数量。先备齐缺少装备的制造材料，再按各项目路线的强化期望消耗同比例分配余额；普通强化材料保持每次强化的用量比例，保护物按期望消耗参与。现有库存优先使用，并为制造、强化直接消耗的金币预留额度。","制造材料也买不齐时，仅按制造用量比例分配；取整后无法利用的余额保留。清单随库存、行情和备料数量更新，只提供采购建议，不执行购买。缺价、未知库存或不完整路线无法分配；当前左一报价不保证实际可成交数量。","从预算采购清单点击材料进入市场，两分钟内打开该物品同等级的购买表单，会一次性预填本次建议数量并保留制造、强化消耗金币；从合计材料进入，则预填全部剩余缺口，金币不够时按表单当前价格填最大可负担数量。卖单不预填，填写后仍需自行确认购买。","挂单成功后，未成交买单和已成交未领取材料计入待收货，与当前库存共同抵扣采购缺口；已扣金币不会再次计作可用余额。部分成交、领取和撤单后自动更新，避免对已下单材料重复分配。待收货不代表已经可以用于制造或强化。","项目和材料按市场左一单价降序排列；金币按 1，未知价格置底。只看缺料会同时保留未知项。","数量减至 1 后，再次点击减号进入移除确认，再点一次移除；也可直接使用移除按钮。","净缺口已扣库存和买单待收；已占用作底子的装备不会重复抵扣。","买单未成仍需等待成交；成交待领需在游戏中领取。","数量按备料方案计算，采购数量向上取整。"]},{title:"市场制作与强化",paragraphs:["打开市场查看当前物品及等级；打开制作进入该物品的直接配方。开始强化会选择背包中低于目标等级的最高等级同物品，并按当前展示路线填写目标等级、保护物和保护起始等级，仍需手动确认开始。缺少物品或保护材料时会提示；多段路线按明细手动准备。制造请自行核对材料与游戏茶槽。"]},{title:"成交历史",paragraphs:["每行对应一个已有成交的本人订单，包含部分成交，记录原挂单价与累计成交量。挂单时间取自订单创建时间；成交耗时上限为挂单至记录时间的间隔，用 ≤ 表示，仅针对已成交部分，不代表整单售罄耗时。缺少挂单时间或时间异常时显示未知；旧记录再次读取到同一订单的创建时间后可补齐，已从游戏移除且未保存创建时间的订单无法恢复。数据源未提供实际成交价和成交时间；原挂单价仅供对照，记录时间不是成交时间，离线或后续订单更新可能使耗时上限偏大。"]},{title:"设置与虚拟角色",paragraphs:["排序、筛选、搜索词及各区块展开状态会自动保存在当前浏览器与站点，刷新后恢复，并包含在本地备份中。未提交输入、删除确认和页面滚动位置不跨刷新恢复。","阈值须依次递增。颜色仅按工时费分档，达到阈值进入下一档；亏损或持平使用对应颜色，不受利润率评级影响。","切换后立即生效；启用时修改下方参数会自动保存并重算。关闭时读取当前角色已装备物品、技能、建筑、茶与成就。装备等级 -1 表示未装备；虚拟模式按月饼默认计入祝福茶。"]},{title:"本地备份",paragraphs:["导出收藏、参考售价、分区、设置和本服务器各角色的备料车。文件仅保存在本机，不含行情缓存、游戏账号凭据或成交历史。","恢复只覆盖文件内同名数据，未包含的数据保留；备料车按文件中的角色 ID 恢复。恢复前会显示覆盖范围，确认后刷新游戏。"]}];const unifiedSections=sections.map(section=>{if(section.title==="强化计划")return{...section,paragraphs:["强化计划统一显示游戏队列、队列外计划与原备料车，下方共用一张材料与采购表。新增只需加入一次计划。","队列外计划按目标数量抵扣已有达标装备和可用库存底子；原备料车保留新增制作数量与原路线含义。","游戏队列自动同步且参数只读。同款重复时可选择独立新增，或关联队列承担相应数量；核对前不生成采购预填。","材料汇总底子采购、直接制造、强化耗材与保护材料，共享库存和待到账只抵扣一次。",...section.paragraphs.slice(0,3),section.paragraphs[6],"按游戏队列、队列外计划、原备料车的顺序分配预算；每项先安排取得底子与制造，再安排强化耗材，部分备料后停止向后分配。"]};if(section.title==="备料与库存")return{...section,paragraphs:["材料已到账但底子未完成时可以先制造，不要求后续强化耗材也全部备齐。待到账和等待前项制造会分别标记。","跨等级需求按产品合并制造批次；同款保护装备随采购或自制来源备料。未知库存、配方、队列与报价保持未知。","原新增制作路线的库存支撑时长与成功率暂不估算；已知总期望时长和材料采购仍保留。",section.paragraphs[2],section.paragraphs[8]]};if(section.title==="备料车与预算")return{...section,title:"统一备料与预算",paragraphs:[section.paragraphs[0],section.paragraphs[5],section.paragraphs[8],"底子就绪不表示强化材料已齐。缺料、待到账、待制造、待强化与已达标分别显示；所有操作只导航和预填，由玩家手动确认。"]};if(section.title==="收藏与分区")return{...section,paragraphs:section.paragraphs.map((text,index)=>index===2?"原材料分区汇集收藏及计划关联材料，需备与缺口采用强化计划的统一核算结果。":text)};return section});function create(){const document=root.document;const help=document.createElement("details");help.className="mwi-layu-settings-help";app.viewPreferences.bindDetails(help,"help");const heading=document.createElement("summary");heading.textContent=t("帮助");help.append(heading);for(const{title:title,paragraphs:paragraphs}of app.unifiedPlan?unifiedSections:sections){const section=document.createElement("details");app.viewPreferences.bindDetails(section,`help-topic:${title}`);const summary=document.createElement("summary");summary.textContent=t(title);section.append(summary);for(const text of paragraphs){const p=document.createElement("p");p.textContent=t(text);section.append(p)}help.append(section)}return help}app.helpUI=Object.freeze({create:create,sections:sections})})(globalThis);

